# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": llm.MAX_TOKENS,
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    for turn in range(1, max_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = llm.MAX_TOKENS
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        is_last_turn = turn == max_turns
        _tc = "none" if is_last_turn else "auto"
        _tools_resp = None if is_last_turn else responses_tools
        _tools_chat = None if is_last_turn else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    resp = await llm.responses(
                        response_history + response_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=_tools_resp,
                        tool_choice=_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                else:
                    resp = await llm.chat(
                        messages, model=model, tools=_tools_chat, tool_choice=_tc
                    )

                if _log_dir is not None:
                    try:
                        _resp_data = (
                            resp.model_dump()
                            if hasattr(resp, "model_dump")
                            else repr(resp)
                        )
                    except Exception:
                        _resp_data = repr(resp)
                    _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                    trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                _llm_last_err = None
                break  # success

            except Exception as e:
                _llm_last_err = e
                logger.warning(
                    "LLM call failed (turn %d, attempt %d/%d): %s",
                    turn,
                    _attempt,
                    llm.LLM_MAX_RETRIES,
                    trace.redact(str(e)),
                )
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)  # 2s, 4s

        if _llm_last_err is not None:
            e = _llm_last_err
            http_detail = {}
            for key in ("status_code", "llm_provider", "model"):
                val = getattr(e, key, None)
                if val is not None:
                    http_detail[key] = val
            cur = e
            while cur is not None:
                http_resp = getattr(cur, "response", None)
                if http_resp is not None and hasattr(http_resp, "status_code"):
                    http_detail["status"] = getattr(http_resp, "status_code", None)
                    http_detail["url"] = str(getattr(http_resp, "url", ""))
                    http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                    try:
                        http_detail["body"] = http_resp.text
                    except Exception:
                        http_detail["body"] = repr(getattr(http_resp, "content", b""))
                    break
                cur = getattr(cur, "original_exception", None) or getattr(
                    cur, "__cause__", None
                )
            logger.warning(
                "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                _attempt,
                turn,
                trace.redact(str(e)),
                trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
            )
            stop_reason = f"llm_error: {e}"
            break

        usage = {
            "role": "primary",
            "turn": turn,
            "model": model,
            "call_id": getattr(resp, "id", None),
            "latency_seconds": time.monotonic() - request_started,
            "usage": llm.usage_dict(resp),
        }
        ctx.model_usage.append(usage)
        trace.event("model_usage", **usage)
        failure = llm.response_error(resp, responses_api=use_responses_api)
        if failure:
            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            messages.append({"role": "assistant", "content": final_answer})
            if final_action == "continue" and feedback:
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            answer = final_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            try:
                result = await _dispatch(name, args, ctx)
            except Exception as e:
                result = f"tool error: {e}"
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": result,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                f"Tool: {name}\n"
                                f"Arguments: {json.dumps(args, ensure_ascii=False)}\n"
                                f"Result:\n{result}"
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            try:
                inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    f"Tool: {inj_name}\n"
                    f"Arguments: {json.dumps(inj_args, ensure_ascii=False)}\n"
                    f"Result:\n{inj_result}"
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    def _clean_answer(text: str) -> str:
        return re.sub(
            r"<｜｜DSML｜｜tool_calls>.*?(?:</｜｜DSML｜｜tool_calls>|\Z)",
            "",
            text,
            flags=re.DOTALL,
        ).strip()

    answer = _clean_answer(answer)

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages, model=model, tools=None, tool_choice="none"
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    answer = forced
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

texts.1a5b9ebca803dc88b1cb001cc71d607a32aa1cac:
"""Supervisor completion protocol gate.

AppWorld tasks are graded only after the agent submits through
``apis.supervisor.complete_task``, and that call has a strict answer protocol:
action tasks must use the default ``answer=None`` while question tasks need a
concise canonical answer. Many otherwise-correct runs lose points because they
(a) never make the completion call, or (b) make it with a long descriptive
``answer`` on an action task.

This middleware enforces the protocol at the execution layer:

* ``before_tool`` inspects shell commands that are about to call
  ``complete_task``. If the task is an action task and the call supplies a
  non-None answer, or the task is a question and the supplied answer is a long
  descriptive string, the command is skipped and the model gets a bounded,
  actionable correction instead.
* ``after_tool`` records only a *successful* completion call (the supervisor
  returns ``Marked the active task complete.``).
* ``before_final`` refuses plain-text final answers until a successful
  completion call has been observed, so the model cannot end the run with a
  prose answer that never reaches the supervisor.

The gate is deliberately generic: it keys on the supervisor API name and the
task text, not on any task ID or expected answer.
"""

from __future__ import annotations

import ast
import re
from typing import Any

_COMPLETE_CALL_RE = re.compile(r"\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_QUESTION_ANSWER_CHARS = 100


def _is_appworld(ctx) -> bool:
    """Only enforce when the question belongs to the AppWorld supervisor API."""
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question


def _task_instruction(question: str) -> str:
    question = question.strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(question: str) -> bool:
    instruction = _task_instruction(question)
    if not instruction:
        return False
    if instruction.endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _split_top_level_args(s: str) -> list[str]:
    """Split ``key=value, key=value`` at top-level commas.

    Respects quotes and nested (), [] and {} so string values containing
    commas (e.g. ``answer="Sent A, B, and C"``) stay intact.
    """
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    quote: str | None = None
    esc = False
    for ch in s:
        if quote:
            buf.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == quote:
                quote = None
            continue
        if ch in ("'", '"'):
            quote = ch
            buf.append(ch)
            continue
        if ch in "([{":
            depth += 1
            buf.append(ch)
            continue
        if ch in ")]}":
            depth = max(0, depth - 1)
            buf.append(ch)
            continue
        if ch == "," and depth == 0:
            parts.append("".join(buf).strip())
            buf = []
            continue
        buf.append(ch)
    if buf:
        parts.append("".join(buf).strip())
    return parts


def _iter_complete_task_calls(command: str):
    """Yield each ``...complete_task(...)`` call text found in ``command``."""
    normalized = command.replace('\\"', '"').replace("\\'", "'")
    for m in _COMPLETE_CALL_RE.finditer(normalized):
        start = m.end() - 1  # position of '('
        depth = 0
        j = start
        while j < len(normalized):
            ch = normalized[j]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    yield normalized[m.start() : j + 1]
                    break
            j += 1


def _answer_info(call_text: str) -> dict[str, Any]:
    """Return info about the ``answer`` keyword inside one complete_task call."""
    inner = call_text[call_text.find("(") + 1 : -1]
    value: str | None = None
    for part in _split_top_level_args(inner):
        if "=" not in part:
            continue
        key, val = part.split("=", 1)
        if key.strip() == "answer":
            value = val.strip()
            break

    if value is None:
        return {"provided": False}
    if value.lower() in ("none", "null"):
        return {"provided": True, "is_none": True}
    if value == "":
        return {"provided": True, "is_none": False, "literal": "", "length": 0}

    if value[0] in ("'", '"'):
        try:
            parsed = ast.literal_eval(value)
        except Exception:
            parsed = value
        if not isinstance(parsed, str):
            parsed = str(parsed)
        return {"provided": True, "is_none": False, "literal": parsed, "length": len(parsed)}

    return {"provided": True, "is_none": False, "raw": value}


async def before_tool(name: str, args: dict, ctx) -> dict | None:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = args.get("command")
    if not isinstance(command, str) or ".complete_task" not in command:
        return None

    is_question = _is_question_task(ctx.question)
    calls = list(_iter_complete_task_calls(command))
    if not calls:
        return None

    for call_text in calls:
        info = _answer_info(call_text)
        if not info.get("provided"):
            continue
        if info.get("is_none"):
            continue

        if not is_question:
            return {
                "action": "skip",
                "result": (
                    "Blocked by completion_protocol_gate: this is a non-question "
                    "action task, so supervisor.complete_task must be called with "
                    "no answer argument (or answer=None). Your shell command was "
                    "NOT executed. Read the complete_task docs and call "
                    "apis.supervisor.complete_task() again without a descriptive answer."
                ),
            }

        literal = info.get("literal")
        if isinstance(literal, str) and len(literal) > _MAX_QUESTION_ANSWER_CHARS:
            return {
                "action": "skip",
                "result": (
                    "Blocked by completion_protocol_gate: question tasks require "
                    "the exact concise canonical answer (a number, yes/no, or a "
                    "short name/entity). Your answer is a long description and "
                    "was NOT submitted. Re-read the question, determine the single "
                    "requested value, and call "
                    "apis.supervisor.complete_task(answer=<concise value>) again."
                ),
            }

    return None


async def after_tool(name: str, args: dict, result: str, ctx) -> None:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = args.get("command")
    if not isinstance(command, str) or ".complete_task" not in command:
        return None
    if "Marked the active task complete" in result:
        state = ctx.state.setdefault("completion_protocol_gate", {})
        state["task_completed"] = True
    return None


async def before_final(answer: str, ctx) -> dict | None:
    if not _is_appworld(ctx):
        return None
    state = ctx.state.get("completion_protocol_gate", {})
    if state.get("task_completed"):
        return None
    if not answer or not answer.strip():
        return None
    return {
        "action": "continue",
        "feedback": (
            "You have not successfully called apis.supervisor.complete_task yet, "
            "so the task has not been submitted. Use the shell tool to call it "
            "now with the protocol-correct answer: no answer / answer=None for "
            "action tasks, or the exact concise canonical answer for question "
            "tasks. Then give a short final message."
        ),
    }

texts.1dcd5d5c302824076abb0000d19e3d708e3ad8fa:
"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


def _recovered_assistant_message(msg: Any, content: str, tc_list: list[dict]) -> dict:
    """Serialize an assistant message while replacing text with recovered tool calls."""
    serialized = _serialize_assistant(msg)
    serialized["content"] = content or ""
    serialized["tool_calls"] = [
        {
            "id": tc["id"],
            "type": "function",
            "function": {
                "name": tc["name"],
                "arguments": tc["arguments"],
            },
        }
        for tc in tc_list
    ]
    return serialized


_DSML_INVOKE_RE = re.compile(
    r"<｜｜DSML｜｜\s*invoke\s+name=[\"']?([^\"'>\s]+)[^>]*>(.*?)</｜｜DSML｜｜\s*invoke\s*>",
    re.DOTALL,
)
_DSML_PARAM_RE = re.compile(
    r"<｜｜DSML｜｜\s*parameter\s+name=[\"']?([^\"'>\s]+)[^>]*>(.*?)</｜｜DSML｜｜\s*parameter\s*>",
    re.DOTALL,
)


def _extract_dsml_calls(
    text: str, *, known_tools: set[str], turn: int = 0, max_calls: int = 4
) -> list[dict]:
    """Recover native tool-call dicts from DSML markup emitted as text.

    Some chat models emit ``<｜｜DSML｜｜ calls>...`` as assistant content instead
    of a tool_calls payload. Recover only known tool names and a bounded number
    of calls so the intended action actually executes instead of ending the run
    as an unparsed final answer.
    """
    calls: list[dict] = []
    for match in _DSML_INVOKE_RE.finditer(text):
        name = match.group(1).strip()
        if name not in known_tools:
            continue
        args: dict[str, str] = {}
        body = match.group(2)
        for param in _DSML_PARAM_RE.finditer(body):
            pname = param.group(1).strip()
            pvalue = param.group(2)
            # DSML parameter text commonly escapes double quotes as \".
            pvalue = pvalue.replace('\\"', '"')
            if pname == "command":
                pvalue = pvalue.strip()
            args[pname] = pvalue
        if name == "shell" and not args.get("command", "").strip():
            continue
        calls.append(
            {
                "id": f"dsml_{turn}_{len(calls) + 1}",
                "name": name,
                "arguments": json.dumps(args, ensure_ascii=False),
            }
        )
        if len(calls) >= max_calls:
            break
    return calls


def _strip_dsml_blocks(text: str) -> str:
    """Remove DSML tag blocks from a final-answer candidate."""
    open_prefix = "<｜｜DSML｜｜"
    close_prefix = "</｜｜DSML｜｜"
    out: list[str] = []
    i = 0
    depth = 0
    while i < len(text):
        if text.startswith(close_prefix, i):
            if depth > 0:
                depth -= 1
            end = text.find(">", i)
            i = end + 1 if end != -1 else i + 1
            continue
        if text.startswith(open_prefix, i):
            depth += 1
            end = text.find(">", i)
            i = end + 1 if end != -1 else i + 1
            continue
        if depth == 0:
            out.append(text[i])
        i += 1
    return "".join(out).strip()


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": llm.MAX_TOKENS,
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    for turn in range(1, max_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = llm.MAX_TOKENS
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        is_last_turn = turn == max_turns
        _tc = "none" if is_last_turn else "auto"
        _tools_resp = None if is_last_turn else responses_tools
        _tools_chat = None if is_last_turn else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    resp = await llm.responses(
                        response_history + response_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=_tools_resp,
                        tool_choice=_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                else:
                    resp = await llm.chat(
                        messages, model=model, tools=_tools_chat, tool_choice=_tc
                    )

                if _log_dir is not None:
                    try:
                        _resp_data = (
                            resp.model_dump()
                            if hasattr(resp, "model_dump")
                            else repr(resp)
                        )
                    except Exception:
                        _resp_data = repr(resp)
                    _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                    trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                _llm_last_err = None
                break  # success

            except Exception as e:
                _llm_last_err = e
                logger.warning(
                    "LLM call failed (turn %d, attempt %d/%d): %s",
                    turn,
                    _attempt,
                    llm.LLM_MAX_RETRIES,
                    trace.redact(str(e)),
                )
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)  # 2s, 4s

        if _llm_last_err is not None:
            e = _llm_last_err
            http_detail = {}
            for key in ("status_code", "llm_provider", "model"):
                val = getattr(e, key, None)
                if val is not None:
                    http_detail[key] = val
            cur = e
            while cur is not None:
                http_resp = getattr(cur, "response", None)
                if http_resp is not None and hasattr(http_resp, "status_code"):
                    http_detail["status"] = getattr(http_resp, "status_code", None)
                    http_detail["url"] = str(getattr(http_resp, "url", ""))
                    http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                    try:
                        http_detail["body"] = http_resp.text
                    except Exception:
                        http_detail["body"] = repr(getattr(http_resp, "content", b""))
                    break
                cur = getattr(cur, "original_exception", None) or getattr(
                    cur, "__cause__", None
                )
            logger.warning(
                "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                _attempt,
                turn,
                trace.redact(str(e)),
                trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
            )
            stop_reason = f"llm_error: {e}"
            break

        usage = {
            "role": "primary",
            "turn": turn,
            "model": model,
            "call_id": getattr(resp, "id", None),
            "latency_seconds": time.monotonic() - request_started,
            "usage": llm.usage_dict(resp),
        }
        ctx.model_usage.append(usage)
        trace.event("model_usage", **usage)
        failure = llm.response_error(resp, responses_api=use_responses_api)
        if failure:
            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        dsml_recovered = False
        if not use_responses_api and not tc_list and content.strip():
            recovered_calls = _extract_dsml_calls(
                content,
                known_tools=set(bundle.tool_names),
                turn=turn,
            )
            if recovered_calls:
                dsml_recovered = True
                content = _strip_dsml_blocks(content)
                tc_list = recovered_calls
                trace.event(
                    "dsml_recovered",
                    turn=turn,
                    n_calls=len(recovered_calls),
                    remaining_content=content,
                )

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            messages.append({"role": "assistant", "content": final_answer})
            if final_action == "continue" and feedback:
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            answer = final_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            if dsml_recovered:
                messages.append(_recovered_assistant_message(msg, content, tc_list))
            else:
                messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            try:
                result = await _dispatch(name, args, ctx)
            except Exception as e:
                result = f"tool error: {e}"
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": result,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                f"Tool: {name}\n"
                                f"Arguments: {json.dumps(args, ensure_ascii=False)}\n"
                                f"Result:\n{result}"
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            try:
                inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    f"Tool: {inj_name}\n"
                    f"Arguments: {json.dumps(inj_args, ensure_ascii=False)}\n"
                    f"Result:\n{inj_result}"
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    def _clean_answer(text: str) -> str:
        return _strip_dsml_blocks(text)

    answer = _clean_answer(answer)

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages, model=model, tools=None, tool_choice="none"
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    answer = forced
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

texts.2239a095bb58625ea4a6d32d00d3a14f3bb70b05:
"""Recover DSML tool-call markup as native shell tool calls.

Some model backends emit tool calls as DSML text in the assistant message
instead of using the OpenAI ``tool_calls`` field.  When that happens the
runtime sees a plain-text final answer, the intended shell command is never
executed, and an AppWorld action task is graded as never completed.

This ``after_llm`` hook handles Chat Completions responses only.  It parses
``invoke name="shell"`` blocks, extracts the ``command`` parameter verbatim,
and returns a response whose native ``tool_calls`` contains that shell call so
the normal tool-call loop executes it.  Responses/API adapter objects are left
untouched: synthetic function calls there would corrupt provider-side call-id
history, and the existing final-answer gate still covers plain-text final
markup on that path.

The hook is deliberately conservative:

* it only fires for AppWorld-shaped questions (``Supervisor:`` /
  ``AppWorld tools are available``);
* it only fires on Chat Completions responses with no native tool calls;
* it never retries on its own.
"""

from __future__ import annotations

import json
import re
import uuid
from types import SimpleNamespace
from typing import Any

_INVOKE_RE = re.compile(
    r"<[|｜]*DSML[|｜]*\s+invoke\s+name=\"(?P<name>[^\"]+)\"\s*>"
    r"(?P<body>.*?)</[|｜]*DSML[|｜]*\s+invoke\s*>",
    re.IGNORECASE | re.DOTALL,
)
_COMMAND_PARAM_RE = re.compile(
    r"<[|｜]*DSML[|｜]*\s+parameter\s+name=\"command\"[^>]*>"
    r"(?P<command>.*?)</[|｜]*DSML[|｜]*\s+parameter\s*>",
    re.IGNORECASE | re.DOTALL,
)
_DSML_OPEN_RE = re.compile(r"<[|｜]*DSML[|｜]*", re.IGNORECASE)


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "AppWorld tools are available" in question:
        return True
    return "Supervisor:" in question and "Current simulated datetime:" in question


def _looks_like_chat_completion(resp: Any) -> bool:
    """True only for Chat Completions objects, not Responses/adapters."""
    if resp is None:
        return False
    if hasattr(resp, "output") or hasattr(resp, "_original_call_ids"):
        return False
    return bool(getattr(resp, "choices", None))


def _has_dsml_invoke(text: str) -> bool:
    lowered = (text or "").lower()
    return "dsml" in lowered and "invoke name=" in lowered


def _prefix_before_dsml(text: str) -> str:
    match = _DSML_OPEN_RE.search(text)
    if not match:
        return text
    return text[: match.start()].strip()


def _parse_dsml_shell_commands(text: str) -> list[str]:
    commands: list[str] = []
    for match in _INVOKE_RE.finditer(text):
        name = match.group("name") or ""
        if name != "shell":
            continue
        body = match.group("body") or ""
        param = _COMMAND_PARAM_RE.search(body)
        if not param:
            continue
        command = (param.group("command") or "").strip()
        if command:
            commands.append(command)
    return commands


def _make_shell_tool_call(call_id: str, command: str) -> Any:
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(
            name="shell",
            arguments=json.dumps({"command": command}, ensure_ascii=False),
        ),
    )


async def after_llm(resp: Any, ctx) -> Any:
    """Convert DSML-only Chat Completions output into native ``shell`` calls."""
    if not _is_appworld(ctx):
        return resp
    if not _looks_like_chat_completion(resp):
        return resp

    try:
        msg = resp.choices[0].message
    except (AttributeError, IndexError, TypeError):
        return resp

    content = getattr(msg, "content", None) or ""
    if not content:
        return resp

    existing_tool_calls = getattr(msg, "tool_calls", None) or []
    if existing_tool_calls:
        return resp

    if not _has_dsml_invoke(content):
        return resp

    try:
        commands = _parse_dsml_shell_commands(content)
    except Exception as e:
        ctx.trace.event("dsml_recovery_error", error=str(e))
        return resp

    if not commands:
        return resp

    tool_calls = [
        _make_shell_tool_call("dsml_" + uuid.uuid4().hex[:12], command)
        for command in commands
    ]
    new_message = SimpleNamespace(
        role="assistant",
        content=_prefix_before_dsml(content),
        reasoning_content=getattr(msg, "reasoning_content", None),
        tool_calls=tool_calls,
    )
    new_choice = SimpleNamespace(message=new_message, finish_reason="tool_calls")
    new_resp = SimpleNamespace(
        id=getattr(resp, "id", None),
        model=getattr(resp, "model", None),
        usage=getattr(resp, "usage", None),
        choices=[new_choice],
    )
    ctx.trace.event(
        "dsml_recovery",
        recovered=len(tool_calls),
        chars=len(content),
    )
    return new_resp

texts.32314bdd9175f44149876184837a9cc19efac2e6:
"""Recover native tool calls that the model emitted as message text.

Some models emit a shell command inside DSML markup or as a bare command
string instead of using the tool-call payload. The kernel accepts those as
final text, which then never executes. This middleware runs after each LLM
response for both API shapes and converts recognized text back into real tool
calls so the intended action executes instead of ending the run.

It only recovers:
  * DSML <invoke> blocks whose target tool exists in this workspace, and
  * a single bare shell command when the whole message is clearly a command.
"""

from __future__ import annotations

import json
import re
from types import SimpleNamespace
from typing import Any

_DSML_BAR = r"(?:[|｜]{1,2})"
_DSML_INVOKE_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s*>",
    re.DOTALL,
)
_DSML_PARAM_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s*>",
    re.DOTALL,
)

_MAX_RECOVERED_CALLS = 4


def _get_content(response: Any) -> str:
    """Best-effort extraction of assistant text from either API shape."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return getattr(msg, "content", "") or ""
    except Exception:
        pass
    return getattr(response, "content", "") or ""


def _get_tool_calls(response: Any) -> list:
    """Return existing native tool calls without mutating anything."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return list(getattr(msg, "tool_calls", None) or [])
    except Exception:
        pass
    return list(getattr(response, "tool_calls", None) or [])


def _strip_code_fences(text: str) -> str:
    text = text.strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:[A-Za-z0-9_+-]+)?\s*", "", text, count=1)
        text = re.sub(r"\s*```$", "", text)
    return text.strip()


def _strip_dsml_blocks(text: str) -> str:
    """Remove DSML tag regions while keeping prose between them."""
    open_marker = re.compile(r"<\s*(?:[|｜]{1,2})\s*DSML\b")
    close_marker = re.compile(r"</\s*(?:[|｜]{1,2})\s*DSML\b")
    out: list[str] = []
    i = 0
    depth = 0
    while i < len(text):
        if close_marker.match(text, i):
            if depth > 0:
                depth -= 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if open_marker.match(text, i):
            depth += 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if depth == 0:
            out.append(text[i])
        i += 1
    return "".join(out).strip()


def _extract_dsml_calls(text: str, known_tools: set[str], turn: int) -> list[dict]:
    """Parse DSML invoke blocks into runtime tool-call dicts (bounded)."""
    calls: list[dict] = []
    for match in _DSML_INVOKE_RE.finditer(text):
        name = match.group(1).strip()
        if name not in known_tools:
            continue
        body = match.group(2)
        args: dict[str, str] = {}
        for param in _DSML_PARAM_RE.finditer(body):
            pname = param.group(1).strip()
            pvalue = param.group(2).replace('\\"', '"')
            if pname == "command":
                pvalue = pvalue.strip()
            args[pname] = pvalue
        if name == "shell" and not args.get("command", "").strip():
            continue
        calls.append(
            {
                "id": f"recover_{turn}_{len(calls) + 1}",
                "name": name,
                "arguments": json.dumps(args, ensure_ascii=False),
            }
        )
        if len(calls) >= _MAX_RECOVERED_CALLS:
            break
    return calls


def _looks_like_bare_shell_command(text: str) -> bool:
    """True only for a clear, standalone shell command, not prose."""
    text = _strip_code_fences(text)
    if not text:
        return False
    first_line = text.splitlines()[0].strip()
    if first_line.startswith(
        ("cd /opt/flashrsi-lite", "/opt/flashrsi-lite", "print(apis.", "apis.")
    ):
        return True
    if "appworld_client.py execute" in first_line:
        return True
    return False


def _make_native_tool_call(call: dict) -> SimpleNamespace:
    return SimpleNamespace(
        id=call["id"],
        type="function",
        function=SimpleNamespace(name=call["name"], arguments=call["arguments"]),
    )


def _apply_recovered(response: Any, content: str, calls: list[dict]) -> Any:
    """Apply recovered content/tool calls to either API response shape."""
    native_calls = [_make_native_tool_call(c) for c in calls]

    # Responses-API middleware adapter (or any object with content/tool_calls).
    if hasattr(response, "tool_calls") and hasattr(response, "content"):
        try:
            response.content = content
            response.tool_calls = native_calls
            return response
        except Exception:
            pass

    # Chat Completions shape. Mutate the original message when possible so
    # later middleware and the kernel's serializer see the recovered call.
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            try:
                msg.content = content
                msg.tool_calls = native_calls
                return response
            except Exception:
                pass
            new_msg = SimpleNamespace(
                role="assistant",
                content=content,
                reasoning_content=getattr(msg, "reasoning_content", "") or "",
                tool_calls=native_calls,
            )
            return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])
    except Exception:
        pass

    # Last resort: assume the object exposes content/tool_calls directly.
    response.content = content
    response.tool_calls = native_calls
    return response


async def after_llm(response, ctx):
    content = _get_content(response)
    existing = _get_tool_calls(response)
    if existing or not content or not content.strip():
        return response

    known_tools = set(getattr(ctx.workspace, "tool_names", []) or [])
    recovered: list[dict] = []

    if re.search(r"DSML", content):
        recovered = _extract_dsml_calls(content, known_tools, turn=ctx.turn)
        if recovered:
            content = _strip_dsml_blocks(content)
        else:
            # DSML without a recoverable invoke is left for the final-answer
            # guard; do not treat it as a bare command.
            return response
    elif _looks_like_bare_shell_command(content):
        command = _strip_code_fences(content)
        recovered = [
            {
                "id": f"recover_{ctx.turn}_1",
                "name": "shell",
                "arguments": json.dumps({"command": command}, ensure_ascii=False),
            }
        ]
        content = ""

    if not recovered:
        return response

    ctx.trace.event(
        "text_tool_call_recovered",
        turn=ctx.turn,
        n_calls=len(recovered),
        remaining_content=content,
    )
    return _apply_recovered(response, content, recovered)

texts.32abd1707dbe4ba13d0b5fd5144a7d6efeda48b3:
"""Completion autopilot for AppWorld tasks.

Recurring AppWorld failures happen when the agent finishes its work and then
returns plain text without ever calling ``apis.supervisor.complete_task``.
The prose is treated as the final answer, the supervisor is never told the
task is complete, and the run is graded as a failure even though the side
effects were performed.

This middleware runs ``after_llm``.  For an AppWorld *action* task that has
already used the AppWorld session and has not yet recorded a successful
completion call, it converts the first plain-text final candidate into a
native ``shell`` tool call that executes ``apis.supervisor.complete_task()``.

For an AppWorld *question* task it is more conservative: only a high-confidence
concise answer extracted from the final candidate is auto-submitted via
``apis.supervisor.complete_task(answer=...)``.  Verbose, markdown, or
ambiguous final messages are left for the normal completion-protocol feedback
loop so the model can submit the exact value itself.

The injected call passes through the normal completion guards
(``completion_protocol`` and ``pre_completion_check``), so a premature or
unverified submission is still blocked and the model is told what to verify.

The autopilot is deliberately narrow and bounded:

* it never fires when a completion call already succeeded;
* it never fires on DSML/tool-call markup (``recover_tool_calls`` handles it);
* it injects at most once per run and records an explicit trace event.
"""

from __future__ import annotations

import json
import re
from types import SimpleNamespace
from typing import Any

_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_INJECTIONS_PER_RUN = 1
_MAX_QUESTION_ANSWER_CHARS = 150

_INJECT_ACTION_COMMAND = (
    "/opt/flashrsi-lite/venv/bin/python /opt/flashrsi-lite/appworld_client.py "
    "execute <<'PY'\n"
    "print(apis.supervisor.complete_task())\n"
    "PY"
)

_TOOL_CALL_TEXT_MARKERS = (
    "<|dsml|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
    "<｜｜dsml｜｜",
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(ctx) -> bool:
    instruction = _task_instruction(ctx)
    if not instruction:
        return False
    if instruction.rstrip().endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _completion_succeeded(result) -> bool:
    if not isinstance(result, str):
        return False
    if "Marked the active task complete." in result:
        return True
    compact = result.replace("\\", "")
    return '"task_completed": true' in compact or '"task_completed":true' in compact


def _used_appworld(ctx) -> bool:
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        command = _get_command(rec.requested_args)
        if "appworld_client.py" in command or "apis." in command:
            return True
    return False


def _get_content(response: Any) -> str:
    """Best-effort extraction of assistant text from either API shape."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return getattr(msg, "content", "") or ""
    except Exception:
        pass
    return getattr(response, "content", "") or ""


def _get_tool_calls(response: Any) -> list:
    """Return existing native tool calls without mutating anything."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return list(getattr(msg, "tool_calls", None) or [])
    except Exception:
        pass
    return list(getattr(response, "tool_calls", None) or [])


def _make_native_tool_call(call: dict) -> SimpleNamespace:
    return SimpleNamespace(
        id=call["id"],
        type="function",
        function=SimpleNamespace(name=call["name"], arguments=call["arguments"]),
    )


def _apply_injected(response: Any, call: dict) -> Any:
    """Attach one native tool call to either API response shape."""
    native = _make_native_tool_call(call)

    # Responses-API middleware adapter (or any object with content/tool_calls).
    if hasattr(response, "tool_calls") and hasattr(response, "content"):
        try:
            response.tool_calls = [native]
            return response
        except Exception:
            pass

    # Chat Completions shape. Mutate the original message when possible so
    # later middleware and the runtime serializer see the injected call.
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            try:
                msg.tool_calls = [native]
                return response
            except Exception:
                pass
            new_msg = SimpleNamespace(
                role="assistant",
                content=getattr(msg, "content", "") or "",
                reasoning_content=getattr(msg, "reasoning_content", "") or "",
                tool_calls=[native],
            )
            return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])
    except Exception:
        pass

    # Last resort: assume the object exposes content/tool_calls directly.
    response.tool_calls = [native]
    return response


def _is_concise_answer(text: str) -> bool:
    """True for a short, unadorned value that is safe to auto-submit."""
    if not isinstance(text, str):
        return False
    text = text.strip()
    if not text or len(text) > _MAX_QUESTION_ANSWER_CHARS:
        return False
    if "\n" in text or "\r" in text:
        return False
    low = text.lower()
    if low.startswith("answer") or low.startswith("the answer"):
        return False
    if any(ch in text for ch in ("```", "*", "_", "|", "<", ">")):
        return False
    if text.startswith("#"):
        return False
    if text.rstrip().endswith("?"):
        return False
    if "complete_task" in low or "supervisor" in low:
        return False
    if any(marker in low for marker in _TOOL_CALL_TEXT_MARKERS):
        return False
    return True


def _clean_answer_capture(value: str) -> str:
    """Remove markdown emphasis, surrounding quotes, and whitespace."""
    value = (value or "").strip()
    value = value.strip("*").strip()
    value = value.strip('"').strip("'").strip()
    return value


def _extract_question_answer(content: str) -> str | None:
    """Extract a high-confidence concise answer from a question-task final turn."""
    stripped = (content or "").strip()
    if not stripped:
        return None

    # Prefer an explicit "Answer: ..." line over the whole message, so we do
    # not accidentally submit a label such as "Answer: $786.00" as the value.
    candidates = [stripped] + stripped.splitlines()[:4]
    for line in candidates:
        line = line.strip()
        match = re.match(
            r"^\s*\*{0,2}answer\*{0,2}\s*:\s*(.+?)\s*$",
            line,
            re.IGNORECASE,
        )
        if not match:
            continue
        value = _clean_answer_capture(match.group(1))
        if _is_concise_answer(value):
            return value

    if _is_concise_answer(stripped):
        return stripped
    return None


def _question_inject_command(answer: str) -> str:
    """Build a supervisor.complete_task(answer=...) AppWorld shell command."""
    py_answer = json.dumps(answer, ensure_ascii=False)
    return (
        "/opt/flashrsi-lite/venv/bin/python /opt/flashrsi-lite/appworld_client.py "
        "execute <<'PY'\n"
        f"print(apis.supervisor.complete_task(answer={py_answer}))\n"
        "PY"
    )


async def after_tool(name, args, result, ctx):
    """Record a successful supervisor.complete_task call for our own state."""
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _completion_succeeded(result):
        return None
    state = ctx.state.setdefault("completion_autopilot", {})
    state["completed"] = True
    ctx.trace.event("completion_autopilot_completed")
    return None


async def after_llm(response, ctx):
    if not _is_appworld_run(ctx):
        return response

    state = ctx.state.setdefault("completion_autopilot", {})
    if state.get("completed"):
        return response
    if int(state.get("injections", 0)) >= _MAX_INJECTIONS_PER_RUN:
        return response

    existing = _get_tool_calls(response)
    if existing:
        return response

    content = _get_content(response)
    if not content or not content.strip():
        return response

    low = content.lower()
    if any(marker in low for marker in _TOOL_CALL_TEXT_MARKERS):
        return response

    # Only act when the agent has actually been working in the AppWorld
    # session.  This avoids injecting a completion call into unrelated runs.
    if not _used_appworld(ctx):
        return response

    if _is_question_task(ctx):
        answer = _extract_question_answer(content)
        if not answer:
            return response
        state["injections"] = int(state.get("injections", 0)) + 1
        call = {
            "id": f"autopilot_{ctx.turn}_{state['injections']}",
            "name": "shell",
            "arguments": json.dumps(
                {"command": _question_inject_command(answer)}, ensure_ascii=False
            ),
        }
        ctx.trace.event(
            "completion_autopilot_inject_question",
            turn=ctx.turn,
            count=state["injections"],
        )
        return _apply_injected(response, call)

    state["injections"] = int(state.get("injections", 0)) + 1
    call = {
        "id": f"autopilot_{ctx.turn}_{state['injections']}",
        "name": "shell",
        "arguments": json.dumps({"command": _INJECT_ACTION_COMMAND}, ensure_ascii=False),
    }
    ctx.trace.event(
        "completion_autopilot_inject",
        turn=ctx.turn,
        count=state["injections"],
    )
    return _apply_injected(response, call)

texts.337538179021b00e20b797f6aaf77d5b71045b09:
"""Recover tool calls that the model emitted as message text.

Some models emit tool-call/DSML markup as assistant text instead of using the
native tool-call payload. The runtime would otherwise treat that text as the
final answer and stop. This middleware runs after each LLM response and
converts recognized DSML invoke blocks into native tool calls so the intended
action executes.

It also recovers the two other textual tool-call shapes seen in graded traces:

* a whole assistant message wrapped in a single shell/python code fence whose
  body is an AppWorld shell command; and
* a whole assistant message that is one bare AppWorld shell command line.

Recovery is deliberately narrow: it only turns text into a ``shell`` call when
the extracted command is clearly an AppWorld invocation (``appworld_client.py``
or ``/opt/flashrsi-lite``). Anything it cannot recover is left in place; the
``before_final`` hook then rejects final answers that are still tool-call
markup so a malformed block can never be accepted as the answer.
"""

from __future__ import annotations

import json
import re
from types import SimpleNamespace
from typing import Any

_DSML_BAR = r"(?:[|｜]{1,2})"
_DSML_INVOKE_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s*>",
    re.DOTALL | re.IGNORECASE,
)
_DSML_PARAM_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s*>",
    re.DOTALL | re.IGNORECASE,
)
_CODE_FENCE_RE = re.compile(
    r"^\s*```(?:sh|bash|shell|python|py)?[ \t]*\r?\n(.*?)\r?\n```\s*$",
    re.DOTALL | re.IGNORECASE,
)

_TOOL_CALL_TEXT_MARKERS = (
    "<|DSML|",
    "<｜｜DSML｜｜",
    "<dsml",
    "<tool_calls>",
    "<tool_call>",
    "<function_calls>",
    "<function_call>",
)

_MAX_RECOVERED_CALLS = 4


def _get_content(response: Any) -> str:
    """Best-effort extraction of assistant text from either API shape."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return getattr(msg, "content", "") or ""
    except Exception:
        pass
    return getattr(response, "content", "") or ""


def _get_tool_calls(response: Any) -> list:
    """Return existing native tool calls without mutating anything."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return list(getattr(msg, "tool_calls", None) or [])
    except Exception:
        pass
    return list(getattr(response, "tool_calls", None) or [])


def _strip_dsml_blocks(text: str) -> str:
    """Remove DSML tag regions while keeping prose that appears between them."""
    open_marker = re.compile(r"<\s*(?:[|｜]{1,2})\s*DSML\b", re.IGNORECASE)
    close_marker = re.compile(r"</\s*(?:[|｜]{1,2})\s*DSML\b", re.IGNORECASE)
    out: list[str] = []
    i = 0
    depth = 0
    while i < len(text):
        if close_marker.match(text, i):
            if depth > 0:
                depth -= 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if open_marker.match(text, i):
            depth += 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if depth == 0:
            out.append(text[i])
        i += 1
    return "".join(out).strip()


def _extract_dsml_calls(text: str, known_tools: set[str], turn: int) -> list[dict]:
    """Parse DSML invoke blocks into runtime tool-call dicts (bounded)."""
    calls: list[dict] = []
    for match in _DSML_INVOKE_RE.finditer(text):
        name = match.group(1).strip()
        if name not in known_tools:
            continue
        body = match.group(2)
        args: dict[str, str] = {}
        for param in _DSML_PARAM_RE.finditer(body):
            pname = param.group(1).strip()
            pvalue = param.group(2).replace('\\"', '"')
            if pname == "command":
                pvalue = pvalue.strip()
            args[pname] = pvalue
        if name == "shell" and not args.get("command", "").strip():
            continue
        calls.append(
            {
                "id": f"recover_{turn}_{len(calls) + 1}",
                "name": name,
                "arguments": json.dumps(args, ensure_ascii=False),
            }
        )
        if len(calls) >= _MAX_RECOVERED_CALLS:
            break
    return calls


def _looks_like_appworld_command(command: str) -> bool:
    """True only for a command that would be meaningful in the AppWorld shell."""
    text = (command or "").strip()
    if not text:
        return False
    low = text.lower()
    return (
        "appworld_client.py" in low
        or text.startswith("/opt/flashrsi-lite")
        or text.startswith("cd /opt/flashrsi-lite")
    )


def _extract_fenced_command(text: str) -> str | None:
    """Return the inner command when the whole message is one code fence."""
    match = _CODE_FENCE_RE.match((text or "").strip())
    if not match:
        return None
    command = match.group(1).strip()
    if not command or not _looks_like_appworld_command(command):
        return None
    return command


def _extract_bare_command(text: str) -> str | None:
    """Return the whole message when it is a single bare AppWorld shell line."""
    stripped = (text or "").strip()
    if not stripped or "\n" in stripped or "\r" in stripped:
        return None
    if not _looks_like_appworld_command(stripped):
        return None
    return stripped


def _make_native_tool_call(call: dict) -> SimpleNamespace:
    return SimpleNamespace(
        id=call["id"],
        type="function",
        function=SimpleNamespace(name=call["name"], arguments=call["arguments"]),
    )


def _apply_recovered(response: Any, content: str, calls: list[dict]) -> Any:
    """Apply recovered content/tool calls to either API response shape."""
    native_calls = [_make_native_tool_call(c) for c in calls]

    # Responses-API middleware adapter (or any object with content/tool_calls).
    if hasattr(response, "tool_calls") and hasattr(response, "content"):
        try:
            response.content = content
            response.tool_calls = native_calls
            return response
        except Exception:
            pass

    # Chat Completions shape. Mutate the original message when possible so
    # later middleware and the kernel's serializer see the recovered call.
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            try:
                msg.content = content
                msg.tool_calls = native_calls
                return response
            except Exception:
                pass
            new_msg = SimpleNamespace(
                role="assistant",
                content=content,
                reasoning_content=getattr(msg, "reasoning_content", "") or "",
                tool_calls=native_calls,
            )
            return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])
    except Exception:
        pass

    # Last resort: assume the object exposes content/tool_calls directly.
    response.content = content
    response.tool_calls = native_calls
    return response


async def after_llm(response, ctx):
    content = _get_content(response)
    existing = _get_tool_calls(response)
    if existing or not content or not content.strip():
        return response

    known_tools = set(getattr(ctx.workspace, "tool_names", []) or [])

    recovered: list[dict] = []
    if re.search(r"DSML", content, re.IGNORECASE):
        recovered = _extract_dsml_calls(content, known_tools, turn=ctx.turn)
        if recovered:
            content = _strip_dsml_blocks(content)

    if not recovered:
        command = _extract_fenced_command(content) or _extract_bare_command(content)
        if command:
            recovered = [
                {
                    "id": f"recover_{ctx.turn}_1",
                    "name": "shell",
                    "arguments": json.dumps({"command": command}, ensure_ascii=False),
                }
            ]

    if not recovered:
        # DSML without a recoverable invoke is left for the final-answer
        # guard; do not guess a bare command.
        return response

    ctx.trace.event(
        "text_tool_call_recovered",
        turn=ctx.turn,
        n_calls=len(recovered),
        remaining_content=content,
    )
    return _apply_recovered(response, content, recovered)


async def before_final(answer, ctx):
    text = (answer or "").lower()
    if not any(marker.lower() in text for marker in _TOOL_CALL_TEXT_MARKERS):
        return None

    return {
        "action": "continue",
        "feedback": (
            "Your final message contains tool-call or DSML markup, which does "
            "not execute from message text. If you still need to run a tool, "
            "issue a real tool call now. Otherwise, return only the plain-text "
            "final answer."
        ),
    }

texts.33e331ef8fef9d44abd51ff54ec4ad7ef185a82a:
"""Flatten AppWorld ``execute`` shell results for the main model.

The shell tool returns a JSON envelope and ``appworld_client.py execute``
prints a second JSON envelope inside it.  The model has to read through
double-escaped text before it can see the actual AppWorld output, which burns
context and makes postcondition verification and completion markers harder to
spot.

This ``after_tool`` hook unwraps those two envelopes for AppWorld execute
commands so state reads, error messages, and the ``task_completed`` flag are
immediately visible.  It is deliberately conservative:

* only ``shell`` calls containing ``appworld_client.py execute`` are touched;
* shell-level timeouts and truncation are left untouched;
* malformed JSON is left untouched;
* the flattened result still contains the shell exit code (when non-zero) and
  an explicit ``[task_completed=...]`` marker.

The hook is placed after the completion guard in ``agent.yaml`` so completion
detection still sees the raw result before it is flattened.
"""

from __future__ import annotations

import json
from typing import Any

_EXECUTE_MARKER = "appworld_client.py execute"


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "AppWorld tools are available" in question:
        return True
    return (
        "Supervisor:" in question
        and "Current simulated datetime:" in question
    )


def _get_command(args: Any) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _flatten_execute_result(result: Any) -> str | None:
    if not isinstance(result, str):
        return None
    try:
        outer = json.loads(result)
    except Exception:
        return None
    if not isinstance(outer, dict):
        return None
    if outer.get("timed_out") or outer.get("truncated"):
        return None

    raw_output = outer.get("output", "")
    if not isinstance(raw_output, str) or not raw_output.strip():
        return None

    try:
        inner = json.loads(raw_output)
    except Exception:
        return None
    if not isinstance(inner, dict):
        return None

    core = inner.get("output", "")
    if not isinstance(core, str):
        core = str(core)
    task_completed = inner.get("task_completed")

    parts: list[str] = []
    if outer.get("exit_code") != 0:
        parts.append(f"[shell exit_code={outer['exit_code']}]")
    parts.append(core.strip() if core.strip() else "(no output)")
    parts.append(f"[task_completed={task_completed}]")
    return "\n".join(parts)


async def after_tool(name: str, args: dict, result: Any, ctx) -> Any:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if not command or _EXECUTE_MARKER not in command:
        return None
    flattened = _flatten_execute_result(result)
    if flattened is None:
        return None
    return {"result": flattened}

texts.371387db7ef4376cd72ea98d95b2011c75e643fa:
"""Deterministic pre-completion semantic guards.

Before a ``supervisor.complete_task`` call is allowed to run, cheap
deterministic checks catch clear violations of task wording in the executed
shell history. These run before the side-LLM audit and are intentionally narrow:

* relationship sets must be resolved from the authoritative phone-contact
  source when the task names friends/roommates/coworkers/siblings/relatives;
* a playlist creation must not leave ``is_public`` to the API default; and
* a "most-liked" question must verify the private, user-specific liked signal
  rather than only the public like count.
* a paginated list query that returned a full page must be followed by later
  ``page_index`` pagination before completion; and
* when a task asks for "songs in my playlists which I have liked",
  ``show_liked_playlists`` output is a playlist list, not the target song set,
  so a tool-result nudge reminds the model to intersect liked songs with owned
  playlist songs.

Each guard is bounded: after ``_MAX_SKIPS`` skips in a run, or on the final
usable tool turn, the completion call is allowed through so a run can still
finish. Guards are skipped for non-AppWorld tasks.
"""

from __future__ import annotations

import re

_COMPLETION_CALL_RE = re.compile(r"\.complete_task\s*\(")
_RELATIONSHIP_WORDS = ("friend", "roommate", "coworker", "sibling", "relative")
_PHONE_SOURCE_CALLS = (
    "search_contacts(",
    "show_contact_relationships(",
)
_VENMO_SOCIAL_CALLS = (
    "search_friends(",
)
_PRIVATE_LIKED_CALLS = (
    "show_liked_songs(",
    "show_song_privates(",
    "show_album_privates(",
)
_PLAYLIST_CREATION_WORDS = ("create", "new", "add")
_MAX_SKIPS = 3
_MAX_LIKED_PLAYLIST_NUDGES = 2

_PAGE_LIMIT_RE = re.compile(r"page_limit\s*=\s*(\d+)")
_LIST_ITEM_FIELDS = (
    "transaction_id",
    "email_thread_id",
    "song_id",
    "playlist_id",
    "contact_id",
    "text_message_id",
    "album_id",
    "artist_id",
)
_LIKED_SONGS_IN_PLAYLISTS_RE = re.compile(
    r"songs?\s+in\s+my\s+(?:spotify\s+)?playlists?\s+(?:which|that)\s+i\s+have\s+liked",
    re.IGNORECASE,
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _task_instruction(question: str) -> str:
    """Return the first paragraph, which is normally the task itself."""
    question = (question or "").strip()
    idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "appworld_client.py" in question or "Supervisor:" in question


def _executed_commands(ctx) -> list[str]:
    """Return commands from executed shell tool calls, most recent last."""
    commands: list[str] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            commands.append(command)
    return commands


def _executed_records(ctx) -> list[tuple[int, str, str]]:
    """Return ``(seq, command, result)`` for executed shell calls."""
    records: list[tuple[int, str, str]] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if not command:
            continue
        result = (
            getattr(rec, "result_full", None)
            or getattr(rec, "result_preview", "")
            or ""
        )
        records.append((rec.seq, command, result))
    return records


def _has(commands: list[str], needles) -> bool:
    return any(needle in command for command in commands for needle in needles)


def _iter_call_args(command: str, func_name: str):
    """Yield the balanced argument text for each ``func_name(...)`` call."""
    marker = func_name + "("
    idx = 0
    while True:
        idx = command.find(marker, idx)
        if idx < 0:
            break
        start = idx + len(marker)
        depth = 1
        i = start
        quote: str | None = None
        escaped = False
        while i < len(command) and depth > 0:
            char = command[i]
            if quote is not None:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
            else:
                if char in ("'", '"'):
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
            i += 1
        if depth == 0:
            yield command[start : i - 1]
        idx = i


def _has_create_playlist_without_visibility(commands: list[str]) -> bool:
    for command in commands:
        if "create_playlist(" not in command:
            continue
        for args in _iter_call_args(command, "create_playlist"):
            if "is_public" not in args:
                return True
    return False


def _block(ctx, state, message: str):
    state["skips"] = state.get("skips", 0) + 1
    # Require a fresh state-read after this feedback before the next retry.
    checkpoint = ctx.state.setdefault("pre_completion_checkpoint", {})
    checkpoint["checkpoint_seq"] = getattr(ctx, "_tool_seq", 0)
    checkpoint["retries"] = 0
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task call by pre_completion_guards: "
            + message
            + " Run the missing verification/fix through the shell tool, then "
            "call supervisor.complete_task again."
        ),
    }


def _page_limit(command: str) -> int | None:
    match = _PAGE_LIMIT_RE.search(command)
    return int(match.group(1)) if match else None


def _count_item_markers(result: str) -> int:
    if not result:
        return 0
    counts = [result.count(field) for field in _LIST_ITEM_FIELDS]
    return max(counts, default=0)


def _is_pagination_followup(command: str) -> bool:
    """True when a command explicitly requests a later page or loops pages."""
    if re.search(r"page_index\s*=\s*[1-9]", command):
        return True
    if (" for " in command or " while " in command) and "page_index" in command:
        return True
    return False


def _has_unpaginated_full_page(ctx) -> bool:
    """True when an executed full page was never followed by later pagination."""
    records = _executed_records(ctx)
    for seq, command, result in records:
        limit = _page_limit(command)
        if not limit:
            continue
        if _count_item_markers(result) < limit:
            continue
        # The command itself may already paginate in a loop.
        if _is_pagination_followup(command):
            continue
        if any(
            later_seq > seq and _is_pagination_followup(later_command)
            for later_seq, later_command, _ in records
        ):
            continue
        return True
    return False


def _is_liked_songs_in_playlists_task(ctx) -> bool:
    instruction = _task_instruction(ctx.question).lower()
    return bool(_LIKED_SONGS_IN_PLAYLISTS_RE.search(instruction))


async def before_tool(name: str, args: dict, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    if not _COMPLETION_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx):
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    if state.get("skips", 0) >= _MAX_SKIPS:
        return None
    if getattr(ctx, "remaining_turns", 100) <= 1:
        return None

    instruction = _task_instruction(ctx.question).lower()
    commands = _executed_commands(ctx)

    # 1. Relationship set must come from the named authoritative source.
    if any(word in instruction for word in _RELATIONSHIP_WORDS):
        if _has(commands, _VENMO_SOCIAL_CALLS) and not _has(
            commands, _PHONE_SOURCE_CALLS
        ):
            return _block(
                ctx,
                state,
                "this task names a relationship set (friends, roommates, "
                "coworkers, siblings, relatives, etc.), but the executed history "
                "resolved targets from Venmo search_friends and never queried the "
                "authoritative phone contacts. Resolve the set with "
                "apis.phone.search_contacts or "
                "apis.phone.show_contact_relationships, then re-verify coverage.",
            )

    # 2. Playlist visibility must be explicit and verified.
    if any(word in instruction for word in _PLAYLIST_CREATION_WORDS) and "playlist" in instruction:
        if _has_create_playlist_without_visibility(commands):
            return _block(
                ctx,
                state,
                "a playlist was created without an explicit is_public argument, so "
                "visibility was left to the API default. Re-create or update the "
                "playlist with is_public set explicitly (use is_public=True unless "
                "the task explicitly requires a private playlist) and verify the "
                "created playlist's is_public value.",
            )

    # 3. "most-liked" must verify the private liked signal, not only like_count.
    if "most-liked" in instruction or "most liked" in instruction:
        if _has(commands, ("like_count",)) and not _has(
            commands, _PRIVATE_LIKED_CALLS
        ):
            return _block(
                ctx,
                state,
                "the task asks for a 'most-liked' item, but the executed history "
                "used only the public like_count metric. Verify the private, "
                "user-specific liked signal as well (for example "
                "show_liked_songs / show_song_privates / show_album_privates) and "
                "recompute the answer from the reading the task wording supports.",
            )

    # 4. A full page from a paginated list query must be followed by pagination.
    if _has_unpaginated_full_page(ctx):
        return _block(
            ctx,
            state,
            "a paginated list query returned a full page but was never followed "
            "by a later page_index (1,2,...). Paginate the complete window/feed "
            "until a short page is observed, then re-verify coverage before "
            "completing.",
        )

    return None


async def after_tool(name: str, args: dict, result: str, ctx):
    """Nudge when a liked-playlist API is fetched for a liked-songs task."""
    if name != "shell":
        return None
    if not _is_appworld_run(ctx):
        return None

    command = _get_command(args)
    if "show_liked_playlists(" not in command:
        return None
    if not _is_liked_songs_in_playlists_task(ctx):
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    count = state.get("liked_playlist_nudges", 0)
    if count >= _MAX_LIKED_PLAYLIST_NUDGES:
        return None
    state["liked_playlist_nudges"] = count + 1

    return (
        result
        + "\n\n[pre_completion_guards] show_liked_playlists returns the "
        "playlists you have liked, not the songs in your playlists which you "
        "have liked. The target set is show_liked_songs(...) intersected with "
        "the song IDs in your owned playlists (show_playlist / "
        "show_playlist_library). Do not act on liked-playlist songs directly; "
        "verify the intersection before rating or completing."
    )

texts.39b1651b91037406ae860942b53bbc0a9e96298a:
"""Pre-submission audit for AppWorld completion calls.

Before a shell command that actually calls ``supervisor.complete_task`` (or a
similar completion/submit/finish function) is allowed to run, ask a side LLM
to compare the original task's explicit requirements against the observed tool
history and the proposed submission. The audit is stricter for AppWorld tasks
than the earlier generic version:

* action tasks are checked for unverified postconditions, ambiguous
  predicates, wrong relationship sources, incomplete pagination, and
  visibility/status defaults;
* question tasks additionally receive the proposed ``answer`` value, so a
  prose answer or an unverified ambiguous reading is challenged before
  submission.

The audit is generic, conservative, and bounded:

* it runs at most three times per run,
* uncertainty is resolved in favour of the agent (answer NONE), and
* a side-LLM error, empty result, or non-bullet answer lets the call through.
"""

from __future__ import annotations

import json
import re

_MAX_AUDITS_PER_RUN = 3
_HISTORY_CALLS = 22
_FULL_RESULT_CALLS = 6
_MAX_COMMAND_CHARS = 2200
_MAX_FULL_RESULT_CHARS = 2800
_MAX_PREVIEW_CHARS = 350

# A submission/completion call is recognized by a function whose name starts
# with complete/submit/finish and is followed by a parenthesized argument list.
_COMPLETION_CALL_RE = re.compile(r"\b(?:complete|submit|finish)[A-Za-z_]*\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(ctx) -> bool:
    instruction = _task_instruction(ctx)
    if not instruction:
        return False
    if instruction.rstrip().endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _extract_call_params(command: str, match: re.Match) -> str | None:
    """Return the argument text inside the matched completion-style call."""
    start = command.find("(", match.start())
    if start < 0:
        return None
    depth = 1
    i = start + 1
    quote: str | None = None
    escaped = False
    while i < len(command) and depth > 0:
        char = command[i]
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
        else:
            if char in ("'", '"'):
                quote = char
            elif char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
        i += 1
    if depth != 0:
        return None
    return command[start + 1 : i - 1]


def _split_top_level_args(text: str) -> list[str]:
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    quote: str | None = None
    escaped = False
    for ch in text:
        if quote is not None:
            buf.append(ch)
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
            continue
        if ch in ("'", '"'):
            quote = ch
            buf.append(ch)
            continue
        if ch in "([{":
            depth += 1
            buf.append(ch)
            continue
        if ch in ")]}":
            depth = max(0, depth - 1)
            buf.append(ch)
            continue
        if ch == "," and depth == 0:
            parts.append("".join(buf).strip())
            buf = []
            continue
        buf.append(ch)
    if buf:
        parts.append("".join(buf).strip())
    return parts


def _get_kwarg(text: str, key: str) -> str | None:
    for part in _split_top_level_args(text):
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        if k.strip() == key:
            return v.strip()
    return None


def _extract_answer(params: str) -> str | None:
    raw = _get_kwarg(params, "answer")
    if raw is None:
        return None
    raw = raw.strip()
    if raw.lower() in ("none", "null"):
        return None
    if len(raw) >= 2 and raw[0] in ("'", '"') and raw[-1] == raw[0]:
        return raw[1:-1]
    return raw


async def after_tool(name, args, result, ctx):
    """Store full shell results for the auditor without touching runtime code."""
    if name != "shell":
        return None
    state = ctx.state.setdefault("pre_completion_check", {})
    store = state.setdefault("full_results", {})
    index = len(getattr(ctx, "tool_history", []) or [])
    store[str(index)] = result if isinstance(result, str) else str(result)
    if len(store) > 80:
        for old_key in sorted(store, key=lambda k: int(k))[:-80]:
            del store[old_key]
    return None


def _summarize_history(ctx) -> str:
    """Compact recent tool history with fuller results for the most recent calls."""
    records = list(getattr(ctx, "tool_history", []) or [])
    if not records:
        return "(no tool calls recorded yet)"

    state = (getattr(ctx, "state", None) or {}).get("pre_completion_check", {}) or {}
    full_results = state.get("full_results", {}) or {}
    start = max(0, len(records) - _HISTORY_CALLS)
    tail = records[start:]
    full_result_from = max(0, len(tail) - _FULL_RESULT_CALLS)

    lines: list[str] = []
    for offset, rec in enumerate(tail):
        requested = rec.requested_args if isinstance(rec.requested_args, dict) else {}
        command = _get_command(requested)
        if command:
            arg_text = f"shell command: {command[:_MAX_COMMAND_CHARS]}"
        else:
            arg_text = "args: " + json.dumps(requested, ensure_ascii=False, default=str)[
                :_MAX_COMMAND_CHARS
            ]

        global_index = start + offset
        if offset >= full_result_from:
            raw_result = full_results.get(str(global_index)) or rec.result_preview or ""
            result_text = raw_result[:_MAX_FULL_RESULT_CHARS]
        else:
            result_text = (rec.result_preview or "")[:_MAX_PREVIEW_CHARS]

        lines.append(
            f"[{rec.seq}] {rec.executed_name} ({getattr(rec, 'action', 'executed')})\n"
            f"{arg_text}\nresult: {result_text}\n"
        )
    return "\n".join(lines)


def _action_audit_prompt(ctx, history: str, submission: str) -> str:
    task = _task_instruction(ctx)
    return (
        "You are a strict pre-submission auditor for an autonomous agent using "
        "the AppWorld API. The agent is about to execute a shell command that "
        "submits the task. Compare the task below against the agent's tool "
        "history and the proposed submission.\n\n"
        "List ONLY problems that would make the submission wrong or premature:\n"
        "- an explicit task requirement with no confirming evidence in the tool "
        "history;\n"
        "- an ambiguous predicate (for example 'most-liked' may mean highest "
        "public like_count or liked-by-the-user) where only one reading was "
        "verified;\n"
        "- an 'X which Y' phrase where the agent used a nearby set instead of "
        "the exact X-filtered-by-Y set;\n"
        "- a relationship set (friends, roommates, coworkers, siblings, etc.) "
        "resolved from an app social graph instead of the authoritative phone "
        "contacts;\n"
        "- a task requiring action on 'all' items in a feed or time window "
        "where the history stopped after a full page instead of paginating "
        "until an empty or short page;\n"
        "- a created/changed object whose visibility/status attribute was left "
        "to a default instead of being set explicitly and verified;\n"
        "- a submission value that is missing, malformed, or contradicted by "
        "the tool history.\n\n"
        "If every explicit requirement is already confirmed and the submission "
        "looks correct, answer exactly: NONE\n"
        "Give the agent the benefit of the doubt for anything that may be "
        "confirmed outside the shown history. Do not suggest extra work beyond "
        "the task.\n\n"
        f"Task:\n{task}\n\n"
        f"Proposed submission:\n{submission}\n\n"
        f"Agent tool history (most recent last):\n{history}\n\n"
        "Return NONE or a bullet list of short imperative items."
    )


def _question_audit_prompt(ctx, history: str, submission: str, answer: str) -> str:
    task = _task_instruction(ctx)
    return (
        "You are a strict pre-submission auditor for an autonomous agent using "
        "the AppWorld API. The agent is about to submit an answer for a "
        "QUESTION task. Compare the task and tool history with the proposed "
        "answer.\n\n"
        "List ONLY problems that must be fixed before submitting:\n"
        "- the proposed answer is prose, markdown, or explanatory instead of "
        "the exact concise value (a number, yes/no, a name/title, or a short "
        "comma-separated list);\n"
        "- the answer conflicts with the tool history;\n"
        "- the task predicate is ambiguous and only one reading was verified;\n"
        "- the value was computed from the wrong source or incomplete "
        "pagination.\n\n"
        "If the proposed answer is the exact concise canonical value and the "
        "tool history supports it, answer exactly: NONE\n"
        "Give the agent the benefit of the doubt for anything that may be "
        "confirmed outside the shown history. Do not suggest extra work beyond "
        "the task.\n\n"
        f"Task:\n{task}\n\n"
        f"Proposed submission:\n{submission}\n\n"
        f"Proposed answer:\n{answer}\n\n"
        f"Agent tool history (most recent last):\n{history}\n\n"
        "Return NONE or a bullet list of short imperative items."
    )


def _blocking_items(audit: str) -> list[str] | None:
    """Return bullet items only when the auditor clearly listed problems."""
    clean = (audit or "").strip()
    if not clean:
        return None
    first_line = clean.splitlines()[0].strip() if clean.splitlines() else ""
    if re.fullmatch(r"NONE\.?", first_line, re.IGNORECASE):
        return None
    if re.fullmatch(r"No (?:missing|problems|issues).*", clean, re.IGNORECASE):
        return None

    items: list[str] = []
    for line in clean.splitlines():
        stripped = line.strip()
        if re.match(r"^\s*(?:[-*•]|\d+[.)])\s+", line):
            items.append(stripped)
    return items or None


_VERIFY_GATE_MAX = 1
_AMBIGUITY_GATE_MAX = 1
_PRIVATE_LIKED_CALLS = (
    "show_liked_songs(",
    "show_song_privates(",
    "show_album_privates(",
)
_PUBLIC_METRIC_CALLS = ("show_song(",)
_SUPERVISOR_COMPLETE_RE = re.compile(
    r"\b(?:apis\.)?supervisor\.complete_task\s*\("
)


def _is_supervisor_complete(command: str) -> bool:
    return bool(_SUPERVISOR_COMPLETE_RE.search(command))


def _executed_commands(ctx):
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            yield command


def _executed_has(ctx, needles) -> bool:
    return any(
        any(needle in command for needle in needles)
        for command in _executed_commands(ctx)
    )


def _action_verification_gate(ctx, state: dict) -> dict | None:
    """Force one final verification pass before the first action submission."""
    if int(state.get("verify_gate_skips", 0)) >= _VERIFY_GATE_MAX:
        return None
    state["verify_gate_skips"] = int(state.get("verify_gate_skips", 0)) + 1
    ctx.trace.event(
        "pre_completion_verify_gate",
        count=state["verify_gate_skips"],
    )
    return {
        "action": "skip",
        "result": (
            "Before supervisor.complete_task can run, perform a final verification pass. "
            "Re-read the full task below and enumerate every explicit requirement. For each "
            "requirement, run a fresh shell command that reads back the actual state and "
            "prints the relevant fields; then print a checklist mapping every requirement to "
            "its concrete tool-result evidence. Fix and re-verify anything that does not "
            "match. Do not resubmit until every requirement has evidence.\n\nTask:\n"
            + _task_instruction(ctx)
        ),
    }


def _private_public_ambiguity_gate(ctx, state: dict) -> dict | None:
    """Require both public and private readings for most-liked Spotify questions."""
    instruction = _task_instruction(ctx).lower()
    if "most-liked" not in instruction:
        return None
    if "spotify" not in instruction and "playlist" not in instruction:
        return None
    if _executed_has(ctx, _PRIVATE_LIKED_CALLS) and _executed_has(
        ctx, _PUBLIC_METRIC_CALLS
    ):
        return None
    if int(state.get("ambiguity_gate_skips", 0)) >= _AMBIGUITY_GATE_MAX:
        return None
    state["ambiguity_gate_skips"] = int(state.get("ambiguity_gate_skips", 0)) + 1
    ctx.trace.event(
        "pre_completion_ambiguity_gate",
        count=state["ambiguity_gate_skips"],
    )
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task: 'most-liked' is ambiguous between the public "
            "like_count metric on each song and your private liked-library signal. The executed "
            "history only shows one of these readings. Before submitting, verify BOTH readings: "
            "use apis.spotify.show_song() like_count for the public metric, and "
            "apis.spotify.show_liked_songs() or apis.spotify.show_song_privates() for the "
            "private signal. Compare them, choose the title the task wording asks for, then "
            "reissue the completion call."
        ),
    }


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    match = _COMPLETION_CALL_RE.search(command)
    if not match:
        return None
    if not _is_appworld_run(ctx):
        return None

    state = ctx.state.setdefault("pre_completion_check", {})
    is_question = _is_question_task(ctx)
    is_supervisor_complete = _is_supervisor_complete(command)

    # Deterministic gates run before the side-LLM audit. They are bounded to one
    # skip each per run so a stubborn model can still make progress afterward.
    if is_supervisor_complete:
        if not is_question:
            gate = _action_verification_gate(ctx, state)
            if gate is not None:
                return gate
        else:
            gate = _private_public_ambiguity_gate(ctx, state)
            if gate is not None:
                return gate

    count = int(state.get("count", 0))
    if count >= _MAX_AUDITS_PER_RUN:
        return None

    history = _summarize_history(ctx)
    if history == "(no tool calls recorded yet)":
        return None

    params = _extract_call_params(command, match)
    if params is None:
        submission = command[:_MAX_COMMAND_CHARS]
    else:
        open_paren = command.find("(", match.start())
        func_name = command[match.start() : open_paren].strip()
        submission = f"call: {func_name}({params[:_MAX_COMMAND_CHARS]})"

    if is_question:
        answer = _extract_answer(params) if params is not None else None
        prompt = _question_audit_prompt(
            ctx, history, submission, answer if answer is not None else "<missing>"
        )
    else:
        prompt = _action_audit_prompt(ctx, history, submission)

    audit = await ctx.side_text(
        prompt, purpose="pre_completion_check", max_tokens=500
    )
    state["count"] = count + 1
    ctx.trace.event(
        "pre_completion_check",
        count=state["count"],
        task_type="question" if is_question else "action",
        audit_len=len(audit or ""),
    )

    items = _blocking_items(audit)
    if not items:
        return None

    return {
        "action": "skip",
        "result": (
            "Blocked this submission after a pre-submission audit. The auditor "
            "says these items must be fixed first:\n"
            + "\n".join(items)
            + "\n\nRun verification shell commands for each item, then reissue "
            "the submission."
        ),
    }

texts.3c327aeba52f56549344f7676fdb048177dc46e8:
"""Deterministic pre-completion guard for relationship-source failures.

For AppWorld tasks that name a relationship set (friends, roommates, coworkers,
siblings, relatives, etc.), that set must be resolved from the supervisor's
phone contacts via ``apis.phone.search_contacts`` or
``apis.phone.show_contact_relationships``, not from an app social graph such as
Venmo ``search_friends``.

This middleware runs when the agent is about to call
``supervisor.complete_task``. If the executed history used Venmo's social graph
for relationship targets and never queried the authoritative phone-contact
source, the submission is skipped and the model gets a precise correction.
"""

from __future__ import annotations

_RELATIONSHIP_WORDS = ("friend", "roommate", "coworker", "sibling", "relative")
_PHONE_SOURCE_CALLS = (
    "apis.phone.search_contacts(",
    "apis.phone.show_contact_relationships(",
)
_VENMO_SOURCE_CALLS = ("venmo.search_friends(", "apis.venmo.search_friends(")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "appworld_client.py" in question or "Supervisor:" in question


def _is_relationship_task(ctx) -> bool:
    question = (getattr(ctx, "question", "") or "").lower()
    return any(word in question for word in _RELATIONSHIP_WORDS)


def _executed_command_has(ctx, needles) -> bool:
    """True if any executed shell call used one of the given Python API calls."""
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if any(needle in command for needle in needles):
            return True
    return False


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if "complete_task" not in command:
        return None
    if not _is_appworld_run(ctx):
        return None
    if not _is_relationship_task(ctx):
        return None
    if not _executed_command_has(ctx, _VENMO_SOURCE_CALLS):
        return None
    if _executed_command_has(ctx, _PHONE_SOURCE_CALLS):
        return None

    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task call: this task names a "
            "relationship set (friends, roommates, coworkers, siblings, etc.). "
            "Resolve that set from the supervisor's phone contacts with "
            "apis.phone.search_contacts or apis.phone.show_contact_relationships, "
            "not from Venmo search_friends. Re-run the target-set query with the "
            "phone-contact source, then call supervisor.complete_task again."
        ),
    }

texts.4538ef7da9e75a43f4e2fe74ed6db769fd1bdb27:
"""Completion gate for AppWorld runs.

Keeps a run from ending without a successful ``apis.supervisor.complete_task``
call. The gate is inert for non-AppWorld tasks.
"""

from __future__ import annotations

import json

_MARK = "Marked the active task complete."
_DSML_MARK = "<｜｜DSML｜｜"
_FAIL_MARKERS = ("Execution failed", "Traceback", "Exception")


def _is_appworld(ctx) -> bool:
    question = ctx.question or ""
    if "AppWorld" in question or "appworld_client.py" in question:
        return True
    for rec in ctx.tool_history:
        for args in (rec.requested_args, rec.executed_args):
            try:
                text = json.dumps(args, ensure_ascii=False, default=str)
            except Exception:
                text = repr(args)
            if "appworld_client.py" in text:
                return True
    return False


def _completed_task(ctx) -> bool:
    for rec in ctx.tool_history:
        preview = rec.result_preview or ""
        if _MARK in preview:
            return True
        try:
            args_text = json.dumps(rec.executed_args, ensure_ascii=False, default=str)
        except Exception:
            args_text = repr(rec.executed_args)
        if "supervisor.complete_task" not in args_text:
            continue
        if any(marker in preview for marker in _FAIL_MARKERS):
            continue
        return True
    return False


async def before_final(answer, ctx):
    if not _is_appworld(ctx):
        return None
    if _completed_task(ctx):
        return None
    if _DSML_MARK in answer:
        return {
            "action": "continue",
            "feedback": (
                "You emitted a DSML tool call as message text; it did not execute. "
                "Use the real shell tool to run the command you intended, then "
                "verify the result and mark the task complete through "
                "`apis.supervisor.complete_task` before finishing."
            ),
        }
    return {
        "action": "continue",
        "feedback": (
            "You have not marked the task complete. Use the shell tool to call "
            "`apis.supervisor.complete_task(...)` in the AppWorld session. "
            "For an action task pass `answer=None`; for a question task pass the "
            "exact concise answer string. If unsure, read the "
            "`supervisor.complete_task` docs first. Then return a brief final "
            "message."
        ),
    }

texts.4976ee1600943328f36869bc9e205c211998d709:
"""Recover native tool calls emitted as DSML/XML/JSON text.

Some models emit a shell command as assistant text (DeepSeek DSML blocks,
``<tool_calls>`` XML, a JSON tool-call object, or a bare shell command) instead
of using the native ``tool_calls`` API.  The runtime never executes that text,
so the intended work silently never happens.

This ``after_llm`` middleware parses those text forms and appends real tool
calls to the response.  It is deliberately conservative and bounded:

* recovery runs only when the response has no native tool calls;
* only tools registered in the workspace are recovered;
* at most ``_MAX_RECOVERED_CALLS`` calls are recovered per response;
* recovered calls get synthetic ids so the runtime can trace them as injected;
* surrounding prose is preserved and the DSML/XML block is stripped from the
  assistant text before the recovered call is dispatched.
"""

from __future__ import annotations

import html
import json
import re
from types import SimpleNamespace
from typing import Any

_MAX_RECOVERED_CALLS = 3

# DSML/DeepSeek marker bars are either ASCII ``|`` or fullwidth ``\uff5c`` and
# may be repeated (``<||DSML|| ...>`` after normalization by some transports).
_BARS = r"[\uff5c|]+"

_DSML_INVOKE_RE = re.compile(
    rf"<{_BARS}DSML{_BARS}\s+invoke\s+([^>]*)>", re.IGNORECASE
)
_DSML_PARAM_RE = re.compile(
    rf"<{_BARS}DSML{_BARS}\s+parameter\s+([^>]*)>(.*?)</{_BARS}DSML{_BARS}\s+parameter\s*>",
    re.IGNORECASE | re.DOTALL,
)
_DSML_BLOCK_RE = re.compile(
    rf"<{_BARS}DSML{_BARS}\s*(?:calls|tool_calls)[^>]*>.*?</{_BARS}DSML{_BARS}\s*(?:calls|tool_calls)\s*>",
    re.IGNORECASE | re.DOTALL,
)
_DSML_OPEN_RE = re.compile(rf"<{_BARS}DSML{_BARS}", re.IGNORECASE)

_XML_INVOKE_RE = re.compile(r"<invoke\s+([^>]*)>", re.IGNORECASE)
_XML_PARAM_RE = re.compile(
    r"<parameter\s+([^>]*)>(.*?)</parameter\s*>", re.IGNORECASE | re.DOTALL
)
_XML_BLOCK_RE = re.compile(
    r"<(?:tool_calls|function_calls)>.*?</(?:tool_calls|function_calls)>",
    re.IGNORECASE | re.DOTALL,
)

_ATTR_RE = re.compile(
    r"""([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*("([^"]*)"|'([^']*)')""", re.IGNORECASE
)

_BARE_COMMAND_STARTS = (
    "/",
    "./",
    "cd ",
    "python",
    "python3 ",
    "bash ",
    "sh ",
    "zsh ",
    "curl ",
    "wget ",
    "cat ",
    "ls ",
    "find ",
    "grep ",
    "echo ",
    "printf ",
    "node ",
    "perl ",
    "ruby ",
)


def _parse_attrs(attrs: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for m in _ATTR_RE.finditer(attrs or ""):
        key = m.group(1)
        value = m.group(3) if m.group(3) is not None else (m.group(4) or "")
        out[key] = html.unescape(value)
    return out


def _json_or_raw(value: str) -> Any:
    value = value.strip()
    if value.startswith(("{", "[")):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            pass
    return value


def _extract_params_from_dsml_block(block: str) -> dict[str, Any]:
    args: dict[str, Any] = {}
    for m in _DSML_PARAM_RE.finditer(block):
        attrs = _parse_attrs(m.group(1))
        key = attrs.get("name", "").strip()
        if not key:
            continue
        raw = m.group(2)
        string_attr = attrs.get("string", "false").lower()
        args[key] = raw if string_attr in {"true", "1"} else _json_or_raw(raw)
    return args


def _extract_params_from_xml_block(block: str) -> dict[str, Any]:
    args: dict[str, Any] = {}
    for m in _XML_PARAM_RE.finditer(block):
        attrs = _parse_attrs(m.group(1))
        key = attrs.get("name", "").strip()
        if not key:
            continue
        raw = m.group(2)
        string_attr = attrs.get("string", "false").lower()
        args[key] = raw if string_attr in {"true", "1"} else _json_or_raw(raw)
    return args


def _extract_dsml_calls(text: str) -> list[tuple[str, dict[str, Any]]]:
    calls: list[tuple[str, dict[str, Any]]] = []
    for m in _DSML_INVOKE_RE.finditer(text):
        if len(calls) >= _MAX_RECOVERED_CALLS:
            break
        attrs = _parse_attrs(m.group(1))
        name = attrs.get("name", "").strip()
        if not name:
            continue
        start = m.end()
        closing = re.search(
            rf"</{_BARS}DSML{_BARS}\s+invoke\s*>", text[start:], re.IGNORECASE
        )
        next_invoke = _DSML_INVOKE_RE.search(text, start)
        if closing and (next_invoke is None or start + closing.start() < next_invoke.start()):
            block = text[start : start + closing.start()]
        else:
            block = text[start:]
        args = _extract_params_from_dsml_block(block)
        calls.append((name, args))
    return calls


def _extract_xml_calls(text: str) -> list[tuple[str, dict[str, Any]]]:
    calls: list[tuple[str, dict[str, Any]]] = []
    for m in _XML_INVOKE_RE.finditer(text):
        if len(calls) >= _MAX_RECOVERED_CALLS:
            break
        attrs = _parse_attrs(m.group(1))
        name = attrs.get("name", "").strip()
        if not name:
            continue
        start = m.end()
        closing = re.search(r"</invoke\s*>", text[start:], re.IGNORECASE)
        next_invoke = _XML_INVOKE_RE.search(text, start)
        if closing and (next_invoke is None or start + closing.start() < next_invoke.start()):
            block = text[start : start + closing.start()]
        else:
            block = text[start:]
        args = _extract_params_from_xml_block(block)
        calls.append((name, args))
    return calls


def _extract_json_calls(text: str) -> list[tuple[str, dict[str, Any]]]:
    stripped = text.strip()
    if not stripped.startswith("{") or not stripped.endswith("}"):
        return []
    try:
        data = json.loads(stripped)
    except json.JSONDecodeError:
        return []
    if not isinstance(data, dict):
        return []
    if "command" in data and isinstance(data["command"], str):
        return [("shell", {"command": data["command"]})]
    if "name" in data and "arguments" in data:
        args = data["arguments"]
        if isinstance(args, str):
            try:
                parsed_args = json.loads(args)
            except json.JSONDecodeError:
                parsed_args = {"value": args}
        elif isinstance(args, dict):
            parsed_args = dict(args)
        else:
            parsed_args = {"value": args}
        return [(str(data["name"]), parsed_args)]
    return []


def _looks_like_bare_command(text: str) -> str | None:
    stripped = text.strip()
    if not stripped:
        return None
    # Strip a single surrounding ``` code fence if present.
    if stripped.startswith("```"):
        stripped = re.sub(r"^```(?:[A-Za-z0-9_+-]+)?\s*", "", stripped, count=1)
        stripped = re.sub(r"\s*```$", "", stripped)
    stripped = stripped.strip()
    if not stripped:
        return None
    first_line = stripped.splitlines()[0].strip()
    if not any(first_line.startswith(s) for s in _BARE_COMMAND_STARTS):
        return None
    # Reject prose that merely starts with a command-looking word.  A recovered
    # bare command must be the whole message and contain no markdown/prose cues.
    for line in stripped.splitlines():
        lower = line.strip().lower()
        if lower.startswith(
            (
                "**",
                "#",
                "- ",
                "* ",
                "note:",
                "step ",
                "first ",
                "next ",
                "then ",
                "finally ",
                "here ",
                "let ",
                "we ",
                "i ",
                "this ",
                "that ",
            )
        ):
            return None
    return stripped


def _strip_markup(text: str) -> str:
    t = _XML_BLOCK_RE.sub("", text)
    t = _DSML_BLOCK_RE.sub("", t)
    # If only an opening DSML marker remains (e.g. a truncated block), drop the
    # rest of the message: the recovered tool call already captures the command.
    if _DSML_OPEN_RE.search(t):
        t = re.sub(rf"<{_BARS}DSML{_BARS}.*$", "", t, flags=re.IGNORECASE | re.DOTALL)
    return t.strip()


def _existing_tool_calls(response: Any) -> list:
    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        return list(getattr(msg, "tool_calls", None) or [])
    return list(getattr(response, "tool_calls", None) or [])


def _response_content(response: Any) -> str:
    choices = getattr(response, "choices", None)
    if choices:
        return getattr(choices[0].message, "content", None) or ""
    return getattr(response, "content", None) or ""


def _make_tool_call(ctx: Any, idx: int, name: str, args: dict[str, Any]):
    turn = getattr(ctx, "turn", 0) or 0
    return SimpleNamespace(
        id=f"recovered_{turn}_{idx}",
        type="function",
        function=SimpleNamespace(
            name=name,
            arguments=json.dumps(args, ensure_ascii=False),
        ),
    )


def _recover_calls(content: str, ctx: Any) -> list[tuple[str, dict[str, Any]]]:
    calls = _extract_dsml_calls(content)
    if not calls:
        calls = _extract_xml_calls(content)
    if not calls:
        calls = _extract_json_calls(content)
    if not calls:
        command = _looks_like_bare_command(content)
        if command:
            calls = [("shell", {"command": command})]

    available = set(getattr(ctx.workspace, "tool_names", None) or [])
    out: list[tuple[str, dict[str, Any]]] = []
    for name, args in calls:
        if not isinstance(name, str) or not name:
            continue
        if name not in available:
            continue
        if not isinstance(args, dict):
            continue
        out.append((name, args))
        if len(out) >= _MAX_RECOVERED_CALLS:
            break
    return out


def _is_responses_adapter(response: Any) -> bool:
    return hasattr(response, "raw_response") and hasattr(response, "_tool_calls")


async def after_llm(response: Any, ctx: Any):
    if _existing_tool_calls(response):
        return response

    content = _response_content(response)
    if not content or not content.strip():
        return response

    calls = _recover_calls(content, ctx)
    if not calls:
        return response

    tool_calls = [_make_tool_call(ctx, idx, name, args) for idx, (name, args) in enumerate(calls)]
    cleaned_content = _strip_markup(content)

    ctx.trace.event(
        "recover_tool_calls",
        recovered=len(tool_calls),
        names=[tc.function.name for tc in tool_calls],
    )

    if _is_responses_adapter(response):
        try:
            response.content = cleaned_content
        except (AttributeError, TypeError):
            pass
        try:
            response.tool_calls = list(tool_calls)
        except (AttributeError, TypeError):
            pass
        return response

    # Chat Completions path.  Return a plain namespace response so the
    # kernel's serializer builds JSON-safe tool-call dicts instead of relying
    # on the provider object's Pydantic ``model_dump`` for mutated fields.
    choices = getattr(response, "choices", None)
    original_msg = choices[0].message if choices else None
    reasoning = getattr(original_msg, "reasoning_content", None) or ""

    new_msg = SimpleNamespace(
        role="assistant",
        content=cleaned_content,
        reasoning_content=reasoning,
        tool_calls=list(tool_calls),
    )
    return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])

texts.4ac559caeeae0149d77622f1a307bdee5fce4c19:
"""Completion and final-answer guards for tasks with a submission function.

This is one execution-layer mechanism with three hooks:

* ``before_tool`` inspects shell commands that call a task-completion function
  named ``complete_task``. Non-question action tasks must not pass a descriptive
  ``answer`` (the documented protocol requires the default ``None``), and
  question tasks must pass a concise canonical answer rather than prose or no
  answer at all. Invalid calls are skipped before execution and the model gets
  a bounded, actionable correction.

* ``after_tool`` records a *successful* completion call (the function output
  contains a completion marker such as ``Marked the active task complete.`` or
  ``"task_completed": true``).

* ``before_final`` rejects plain-text final answers that are visibly unexecuted
  tool-call/DSML markup or shell commands. When the task instructions document
  a completion API, or when the task is an AppWorld task (identified by the
  supervisor block / appworld client), it also refuses to let the run end until
  a successful completion call has been observed.

The guard keys on the generic function name ``complete_task`` and the presence
of a documented completion API or AppWorld supervisor block. It does not know
any task ID or expected answer and does not hard-code any environment path.
"""

from __future__ import annotations

import re

_DSML_MARKERS = (
    "<｜｜DSML｜｜",
    "<|DSML|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
    "<invoke",
)

_COMPLETE_CALL_RE = re.compile(r"\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_QUESTION_ANSWER_CHARS = 120
_MAX_SKIPS = 3

_SHELL_OR_CODE_PREFIXES = (
    "cd ",
    "ls ",
    "cat ",
    "python",
    "python3",
    "bash",
    "sh ",
    "curl ",
    "wget ",
    "pip ",
    "print(",
    "import ",
    "echo ",
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _task_instruction(question: str) -> str:
    """Return the first paragraph, which is normally the task itself.

    Later paragraphs are usually harness/environment instructions and metadata.
    """
    question = (question or "").strip()
    idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _expects_completion(question: str) -> bool:
    """True when the task instructions document a completion/submission API.

    AppWorld tasks are detected from their supervisor block even when the task
    text itself does not spell out ``complete_task``; otherwise a run can end
    with a final answer and never submit through ``apis.supervisor.complete_task``.
    """
    q = (question or "").lower()
    if "appworld_client.py" in q or "supervisor:" in q:
        return True
    return (
        "complete_task" in q
        or "completion api" in q
        or "completion function" in q
        or "submission function" in q
        or "submission api" in q
    )


def _completion_hint(ctx) -> str:
    q = (getattr(ctx, "question", "") or "").lower()
    if "appworld_client.py" in q or "supervisor:" in q:
        return "apis.supervisor.complete_task"
    return "the task completion function"


def _is_question_task(question: str) -> bool:
    instruction = _task_instruction(question)
    if not instruction:
        return False
    if instruction.endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _iter_complete_calls(command: str):
    """Yield each ``...complete_task(...)`` call text found in ``command``."""
    for m in _COMPLETE_CALL_RE.finditer(command):
        start = m.end() - 1  # position of '('
        depth = 0
        j = start
        quote = None
        escaped = False
        while j < len(command):
            ch = command[j]
            if quote is not None:
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == quote:
                    quote = None
            else:
                if ch in ("'", '"'):
                    quote = ch
                elif ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        yield command[m.start() : j + 1]
                        break
            j += 1


def _extract_quoted(s: str, quote: str) -> tuple[str, int]:
    """Return (raw_content_without_outer_quotes, end_index_after_closing_quote)."""
    buf: list[str] = []
    i = 0
    escaped = False
    while i < len(s):
        ch = s[i]
        if escaped:
            buf.append(ch)
            escaped = False
        elif ch == "\\":
            buf.append(ch)
            escaped = True
        elif ch == quote:
            return "".join(buf), i + 1
        else:
            buf.append(ch)
        i += 1
    return "".join(buf), 0


def _answer_info(call_text: str) -> dict:
    """Return info about the ``answer`` keyword inside one complete_task call."""
    if "(" not in call_text:
        return {"provided": False}
    inner = call_text[call_text.find("(") + 1 : -1]

    if re.search(r"\banswer\s*=\s*(None|null)\b", inner):
        return {"provided": True, "kind": "none"}

    m = re.search(r"\banswer\s*=\s*([\"'])", inner)
    if m:
        quote = m.group(1)
        value, _ = _extract_quoted(inner[m.end() :], quote)
        return {"provided": True, "kind": "string", "value": value}

    m = re.search(r"\banswer\s*=\s*(-?\d+(?:\.\d+)?)", inner)
    if m:
        return {"provided": True, "kind": "number", "value": m.group(1)}

    if re.search(r"\banswer\s*=", inner):
        return {"provided": True, "kind": "other", "value": ""}

    return {"provided": False}


def _looks_like_prose_answer(value: str | None) -> bool:
    text = (value or "").strip()
    if not text:
        return True
    if "\n" in text or "\r" in text:
        return True
    if len(text) > _MAX_QUESTION_ANSWER_CHARS:
        return True
    low = text.lower()
    if low.startswith(("answer:", "**answer:", "the answer is", "task complete", "task:")):
        return True
    if " — " in text or "|" in text or ";" in text:
        return True
    if re.match(r"^[-*#>]", text):
        return True
    return False


def _strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:[A-Za-z0-9_+-]+)?\s*", "", text, count=1)
        text = re.sub(r"\s*```$", "", text)
    return text.strip()


def _looks_like_unexecuted_markup(text: str) -> bool:
    low = (text or "").lower()
    return any(marker.lower() in low for marker in _DSML_MARKERS)


def _looks_like_unexecuted_command(text: str) -> bool:
    stripped = _strip_code_fences(text)
    if not stripped:
        return False
    first_line = stripped.splitlines()[0].strip().lower()
    return first_line.startswith(_SHELL_OR_CODE_PREFIXES)


def _completion_succeeded(result: str) -> bool:
    if "Marked the active task complete." in result:
        return True
    compact = result.replace("\\", "")
    return '"task_completed": true' in compact or '"task_completed":true' in compact


def _task_completed(ctx) -> bool:
    state = ctx.state.setdefault("finalization_gate", {})
    return bool(state.get("task_completed"))


async def before_tool(name: str, args: dict, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    if ".complete_task" not in command:
        return None

    calls = list(_iter_complete_calls(command))
    if not calls:
        return None

    is_question = _is_question_task(ctx.question)
    state = ctx.state.setdefault("finalization_gate", {})

    for call_text in calls:
        info = _answer_info(call_text)

        if not is_question:
            if info.get("provided") and info.get("kind") != "none":
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: this is a non-question action "
                        "task, so the completion function must be called with no "
                        "answer argument (or answer=None). Your shell command was "
                        "NOT executed. Read the completion function docs and call "
                        "the completion function again without a descriptive answer."
                    ),
                }
        else:
            if not info.get("provided") or info.get("kind") not in {"string", "number"}:
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: this is a question task, so "
                        "the completion function must be called with a concise "
                        "answer= value (a number, yes/no, name, title, or short "
                        "list). Your shell command was NOT executed. Submit the "
                        "exact concise answer through the shell tool."
                    ),
                }

            if info.get("kind") == "string" and _looks_like_prose_answer(info.get("value")):
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: the completion answer for a "
                        "question task must be concise and canonical, not prose, a "
                        "breakdown, or markdown. Your shell command was NOT executed. "
                        "Re-read the exact question and submit the short answer value."
                    ),
                }

    return None


async def after_tool(name: str, args: dict, result: str, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if ".complete_task" not in command:
        return None
    if _completion_succeeded(result):
        state = ctx.state.setdefault("finalization_gate", {})
        state["task_completed"] = True
        state["skips"] = 0
    return None


async def before_final(answer: str, ctx):
    text = answer or ""

    if _looks_like_unexecuted_markup(text) or _looks_like_unexecuted_command(text):
        return {
            "action": "continue",
            "feedback": (
                "Your final message contains tool-call markup or a shell command, "
                "which does not execute from message text. If you still need to run "
                "a tool, issue a real shell tool call now. Otherwise, return only the "
                "plain-text final answer."
            ),
        }

    if _expects_completion(ctx.question) and not _task_completed(ctx):
        hint = _completion_hint(ctx)
        return {
            "action": "continue",
            "feedback": (
                "The task requires a completion/submission call, but this run has "
                "not successfully called it yet. Call "
                f"{hint} through the shell tool with the protocol-"
                "correct answer (no answer or answer=None for an action task, or "
                "the exact concise answer for a question task), wait for its "
                "result, then return a short plain-text final message."
            ),
        }

    return None

texts.4edd99a5b4915e206350ec8c96722d1dadee34d0:
"""AppWorld completion lifecycle guard.

This middleware makes the native completion protocol deterministic for AppWorld
tasks.  Three reported failure modes are handled:

1. The run ends without a real ``apis.supervisor.complete_task`` call.  The
   ``before_final`` hook continues the turn whenever an AppWorld task has not
   yet recorded a successful completion, and specifically recovers the common
   case where the model emitted DSML/tool-call markup as message text.

2. Action tasks call ``complete_task(answer='long prose')`` even though the
   supervisor docs require ``answer`` to be left at its default ``None`` for
   non-question tasks.  ``before_tool`` rewrites the command to drop the
   answer argument and executes the corrected call in the same turn.

3. ``after_tool`` records a successful completion only when the AppWorld
   execute result actually reports ``task_completed: true``, so a failed or
   skipped completion cannot satisfy the final gate.

The module is deliberately generic: it keys on the AppWorld supervisor prompt
shape and the task text, never on task IDs or expected answers.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_EXECUTE_MARKER = "appworld_client.py execute"
_COMPLETE_MARKERS = (
    "apis.supervisor.complete_task",
    "supervisor.complete_task",
)
_DSML_MARKERS = (
    "<｜｜DSML｜｜",
    "<|DSML|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
)
_QUESTION_STARTS = {"what", "which", "when", "where", "who", "why", "how"}
_ANSWER_KW_RE = re.compile(r"\banswer\s*=")


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "AppWorld tools are available" in question:
        return True
    return (
        "Supervisor:" in question
        and "Current simulated datetime:" in question
    )


def _instruction(question: str) -> str:
    question = question.strip()
    idx = question.find("\n\nSupervisor:")
    if idx != -1:
        question = question[:idx]
    return question.strip()


def _is_question_task(question: str) -> bool:
    """Return True when the supervisor expects a concise answer value.

    AppWorld question tasks begin with a question word (What/How/Which/...);
    action tasks are imperative.  We also accept a first-sentence '?' as a
    fallback so tasks such as d0b1f43_2 are classified correctly.
    """
    instr = _instruction(question)
    if not instr:
        return False
    first_word = instr.split()[0].strip().lower().rstrip("?.!:;")
    if first_word in _QUESTION_STARTS:
        return True
    first_sentence = instr.splitlines()[0].rstrip() if instr.splitlines() else instr
    return first_sentence.endswith("?")


def _get_command(args: Any) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _find_call_bounds(text: str, start: int) -> tuple[int, int] | None:
    """Return (open_paren, close_paren) for the call starting at ``start``."""
    open_idx = text.find("(", start)
    if open_idx == -1:
        return None
    depth = 0
    single = False
    double = False
    escaped = False
    for j in range(open_idx, len(text)):
        ch = text[j]
        if single:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == "'":
                single = False
            continue
        if double:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                double = False
            continue
        if ch == "'":
            single = True
            continue
        if ch == '"':
            double = True
            continue
        if ch == "(":
            depth += 1
            continue
        if ch == ")":
            depth -= 1
            if depth == 0:
                return open_idx, j
    return None


def _call_has_nondefault_answer(call_text: str) -> bool:
    """True if the call supplies an answer that is not None/null."""
    for match in _ANSWER_KW_RE.finditer(call_text):
        tail = call_text[match.end() :]
        if re.match(r"\s*(?:None|null)\b", tail):
            continue
        return True
    return False


def _extract_answer_value(command: str) -> str | None:
    """Return the literal value passed to ``answer=`` in the first complete_task call."""
    for marker in _COMPLETE_MARKERS:
        idx = command.find(marker)
        if idx == -1:
            continue
        bounds = _find_call_bounds(command, idx + len(marker))
        if bounds is None:
            continue
        open_idx, close_idx = bounds
        call_text = command[open_idx + 1 : close_idx]
        match = re.search(
            r"\banswer\s*=\s*("
            r"'(?:\\.|[^'\\])*'"
            r"|\"(?:\\.|[^\"\\])*\""
            r"|[^,\n\)]+"
            r")",
            call_text,
            re.S,
        )
        if not match:
            return None
        raw = match.group(1).strip()
        if len(raw) >= 2 and raw[0] in ("'", '"'):
            try:
                return str(ast.literal_eval(raw))
            except Exception:
                return raw[1:-1]
        return raw
    return None


def _is_prose_question_answer(value: str) -> bool:
    """True when a question-task answer is too long to be the documented concise value."""
    return len(value) > 120 or "\n" in value or "\r" in value


def _fix_action_complete_task(command: str) -> str | None:
    """Return the command with the answer argument removed, if appropriate."""
    for marker in _COMPLETE_MARKERS:
        idx = command.find(marker)
        if idx == -1:
            continue
        bounds = _find_call_bounds(command, idx + len(marker))
        if bounds is None:
            continue
        open_idx, close_idx = bounds
        call_text = command[open_idx : close_idx + 1]
        if not _call_has_nondefault_answer(call_text):
            return None
        return command[:open_idx] + "()" + command[close_idx + 1 :]
    return None


def _result_says_completed(result: Any) -> bool:
    if not isinstance(result, str):
        return False
    try:
        outer = json.loads(result)
    except Exception:
        return False
    if not isinstance(outer, dict):
        return False
    if outer.get("timed_out") or outer.get("truncated"):
        return False
    if outer.get("exit_code") != 0:
        return False
    raw_output = outer.get("output", "")
    if not isinstance(raw_output, str) or not raw_output.strip():
        return False
    try:
        inner = json.loads(raw_output)
    except Exception:
        return False
    return isinstance(inner, dict) and inner.get("task_completed") is True


def _has_dsml(text: str) -> bool:
    lowered = (text or "").lower()
    return any(marker.lower() in lowered for marker in _DSML_MARKERS)


async def before_tool(name: str, args: dict, ctx) -> Any:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if not command or _EXECUTE_MARKER not in command or "complete_task" not in command:
        return None
    if _is_question_task(ctx.question or ""):
        value = _extract_answer_value(command)
        if value is None or value in ("", "None", "null") or _is_prose_question_answer(value):
            ctx.trace.event(
                "appworld_completion_answer_blocked",
                tool=name,
                length=len(value) if value else 0,
            )
            return {
                "action": "skip",
                "result": (
                    "The AppWorld supervisor.complete_task call was NOT executed "
                    "because the `answer` value is missing or too long/prose. The "
                    "supervisor docs require a concise answer: a number, a yes/no, or "
                    "a specific entity. Compute the concise canonical answer to the "
                    "task and call `apis.supervisor.complete_task(answer='<concise "
                    "answer>')` again."
                ),
            }
        return None

    fixed = _fix_action_complete_task(command)
    if fixed and fixed != command:
        ctx.trace.event("appworld_completion_answer_stripped", tool=name)
        return {"action": "redirect", "name": "shell", "args": {**args, "command": fixed}}
    return None


async def after_tool(name: str, args: dict, result: Any, ctx) -> Any:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if not command or _EXECUTE_MARKER not in command:
        return None
    if _result_says_completed(result):
        state = ctx.state.get("appworld")
        if not isinstance(state, dict):
            state = {}
        state["completed"] = True
        ctx.state["appworld"] = state
        ctx.trace.event("appworld_completion_recorded")
    return None


async def before_final(answer: str, ctx) -> Any:
    if not _is_appworld(ctx):
        return None
    state = ctx.state.get("appworld")
    completed = isinstance(state, dict) and bool(state.get("completed"))
    if completed:
        return None

    if _has_dsml(answer):
        feedback = (
            "You ended with tool-call markup instead of a native tool call, so no "
            "supervisor completion call was executed. Issue a native `shell` tool "
            "call that runs the AppWorld execute Python block and calls "
            "`apis.supervisor.complete_task()`, then return a one-sentence final "
            "message. Do not put the command in message text or DSML markup."
        )
    elif _is_question_task(ctx.question or ""):
        feedback = (
            "This AppWorld question has not been submitted to the supervisor. "
            "Extract the concise answer from your final message and issue a native "
            "`shell` tool call that runs the AppWorld execute Python block with "
            "`apis.supervisor.complete_task(answer=<concise answer>)`. Then return a "
            "one-sentence final message."
        )
    else:
        feedback = (
            "This AppWorld task has not been marked complete. Issue a native `shell` "
            "tool call that runs the AppWorld execute Python block with "
            "`apis.supervisor.complete_task()`, then return a one-sentence final "
            "message. Do not return the command as message text."
        )
    return {"action": "continue", "feedback": feedback}

texts.51db5b8ee0c7f330d6233265a45e4d6169e000c9:
"""Paginated-read completeness guard.

List endpoints are commonly paginated with a ``page_limit``/``page_size`` and a
``page_index``/``page``/``offset`` cursor.  A run that reads only the first full
page and then finalizes can silently miss records, then act on or verify only
the incomplete subset.

This middleware records paginated shell calls and, before the run finalizes,
asks the model to continue pagination when the most recent full page was not
followed by a later page request for the same read.

It is deliberately generic and bounded:

* ``after_tool`` parses the shell envelope and records the page-limit and page
  cursor plus whether the returned row count reached the page limit;
* a command that already loops over pages internally is marked as a paginated
  loop and never triggers the guard;
* ``before_final`` continues at most once per full page and only when no later
  page fetch is visible; the runtime's ``_final_continue_max`` bounds retries.
"""

from __future__ import annotations

import json
import re
from typing import Any

_PAGE_LIMIT_RE = re.compile(r"\b(?:page_limit|page_size|limit|per_page)\s*=\s*(\d+)", re.IGNORECASE)
_PAGE_INDEX_RE = re.compile(r"\b(?:page_index|page_num|page|offset)\s*=\s*(\d+)", re.IGNORECASE)
_LOOP_RE = re.compile(r"\b(?:for|while)\b", re.IGNORECASE)


def _get_command(args: Any) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _parse_limit(command: str) -> int | None:
    m = _PAGE_LIMIT_RE.search(command)
    return int(m.group(1)) if m else None


def _parse_page_index(command: str) -> int:
    indexes = [int(m.group(1)) for m in _PAGE_INDEX_RE.finditer(command)]
    return max(indexes) if indexes else 0


def _count_rows(inner_text: Any) -> int:
    if not isinstance(inner_text, str) or not inner_text.strip():
        return 0
    try:
        data = json.loads(inner_text)
    except json.JSONDecodeError:
        data = None
    if isinstance(data, list):
        return len(data)
    if isinstance(data, dict):
        lists = [v for v in data.values() if isinstance(v, list)]
        return max((len(v) for v in lists), default=0)
    return sum(1 for line in inner_text.splitlines() if line.strip())


def _parse_shell_envelope(result: str) -> tuple[int | None, bool, bool, Any] | None:
    if not isinstance(result, str) or not result.strip():
        return None
    try:
        outer = json.loads(result)
    except json.JSONDecodeError:
        return None
    if not isinstance(outer, dict):
        return None
    exit_code = outer.get("exit_code")
    timed_out = bool(outer.get("timed_out"))
    truncated = bool(outer.get("truncated"))
    raw_output = outer.get("output", "")
    inner_text: Any = raw_output
    # The shell tool often wraps another JSON envelope produced by the command.
    if isinstance(raw_output, str) and raw_output.strip().startswith("{"):
        try:
            inner = json.loads(raw_output)
            if isinstance(inner, dict) and "output" in inner:
                inner_text = inner.get("output", "")
        except json.JSONDecodeError:
            pass
    return exit_code, timed_out, truncated, inner_text


async def after_tool(name: str, args: dict, result: str, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    limit = _parse_limit(command)
    if limit is None or limit <= 0:
        return None

    parsed = _parse_shell_envelope(result)
    if parsed is None:
        return None
    exit_code, timed_out, truncated, inner_text = parsed

    full_page = False
    if exit_code == 0 and not timed_out:
        full_page = _count_rows(inner_text) >= limit

    loop = bool(_LOOP_RE.search(command))
    paginated_loop = loop and bool(_PAGE_INDEX_RE.search(command))

    state = ctx.state.setdefault("pagination_guard", {})
    records = state.setdefault("records", [])
    records.append(
        {
            "seq": len(records),
            "turn": getattr(ctx, "turn", 0) or 0,
            "limit": limit,
            "page_index": _parse_page_index(command),
            "full_page": full_page,
            "loop": loop,
            "paginated_loop": paginated_loop,
            "truncated": truncated,
        }
    )
    return None


async def before_final(answer: str, ctx):
    state = ctx.state.setdefault("pagination_guard", {})
    records = state.get("records", []) or []
    if not records:
        return None

    last_full = None
    last_full_idx = -1
    for idx, rec in enumerate(records):
        if rec.get("full_page") and not rec.get("loop"):
            last_full = rec
            last_full_idx = idx

    if last_full is None:
        return None

    # A later page request or an explicit page loop means pagination was
    # continued for that read.  A loop over contacts/emails with a default page
    # cursor does not count as advancing the page.
    for rec in records[last_full_idx + 1 :]:
        if rec.get("paginated_loop"):
            return None
        if rec.get("page_index", 0) > last_full.get("page_index", 0):
            return None

    if state.get("nudged_for") == last_full.get("seq"):
        return None
    state["nudged_for"] = last_full.get("seq")

    limit = last_full.get("limit", 0)
    page_index = last_full.get("page_index", 0)
    return {
        "action": "continue",
        "feedback": (
            f"The most recent paginated read (page_limit {limit}, "
            f"page_index {page_index}) returned a full page, and no later page "
            "request was observed. If more records may exist, fetch the next "
            f"page (for example page_index={page_index + 1}) or loop until a "
            f"page returns fewer than {limit} rows. After re-checking, re-run "
            "any finalization/submission step your environment requires, then "
            "finalize again."
        ),
    }

