"""Recover tool calls that the model emitted as message text.

Some models emit tool-call/DSML markup as assistant text instead of using the
native tool-call payload. The runtime would otherwise treat that text as the
final answer and stop. This middleware runs after each LLM response and
converts recognized DSML invoke blocks into native tool calls so the intended
action executes.

It only recovers DSML <invoke> blocks whose target tool exists in this
workspace. Anything it cannot recover is left in place; the ``before_final``
hook then rejects final answers that are still tool-call markup so a malformed
block can never be accepted as the answer.
"""

from __future__ import annotations

import json
import re
from types import SimpleNamespace
from typing import Any

_DSML_BAR = r"(?:[|｜]{1,2})"
_DSML_INVOKE_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*invoke\s*>",
    re.DOTALL,
)
_DSML_PARAM_RE = re.compile(
    rf"<\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s+name=[\"']?([^\"'>\s]+)[^>]*>"
    rf"(.*?)</\s*{_DSML_BAR}\s*DSML\s*{_DSML_BAR}\s*parameter\s*>",
    re.DOTALL,
)

_TOOL_CALL_TEXT_MARKERS = (
    "<|DSML|",
    "<｜｜DSML｜｜",
    "<dsml",
    "<tool_calls>",
    "<tool_call>",
    "<function_calls>",
    "<function_call>",
)

_MAX_RECOVERED_CALLS = 4


def _get_content(response: Any) -> str:
    """Best-effort extraction of assistant text from either API shape."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return getattr(msg, "content", "") or ""
    except Exception:
        pass
    return getattr(response, "content", "") or ""


def _get_tool_calls(response: Any) -> list:
    """Return existing native tool calls without mutating anything."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return list(getattr(msg, "tool_calls", None) or [])
    except Exception:
        pass
    return list(getattr(response, "tool_calls", None) or [])


def _strip_dsml_blocks(text: str) -> str:
    """Remove DSML tag regions while keeping prose that appears between them."""
    open_marker = re.compile(r"<\s*(?:[|｜]{1,2})\s*DSML\b")
    close_marker = re.compile(r"</\s*(?:[|｜]{1,2})\s*DSML\b")
    out: list[str] = []
    i = 0
    depth = 0
    while i < len(text):
        if close_marker.match(text, i):
            if depth > 0:
                depth -= 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if open_marker.match(text, i):
            depth += 1
            m = re.match(r"[^>]*>", text[i:])
            i = i + (m.end() if m else 1)
            continue
        if depth == 0:
            out.append(text[i])
        i += 1
    return "".join(out).strip()


def _extract_dsml_calls(text: str, known_tools: set[str], turn: int) -> list[dict]:
    """Parse DSML invoke blocks into runtime tool-call dicts (bounded)."""
    calls: list[dict] = []
    for match in _DSML_INVOKE_RE.finditer(text):
        name = match.group(1).strip()
        if name not in known_tools:
            continue
        body = match.group(2)
        args: dict[str, str] = {}
        for param in _DSML_PARAM_RE.finditer(body):
            pname = param.group(1).strip()
            pvalue = param.group(2).replace('\\"', '"')
            if pname == "command":
                pvalue = pvalue.strip()
            args[pname] = pvalue
        if name == "shell" and not args.get("command", "").strip():
            continue
        calls.append(
            {
                "id": f"recover_{turn}_{len(calls) + 1}",
                "name": name,
                "arguments": json.dumps(args, ensure_ascii=False),
            }
        )
        if len(calls) >= _MAX_RECOVERED_CALLS:
            break
    return calls


def _make_native_tool_call(call: dict) -> SimpleNamespace:
    return SimpleNamespace(
        id=call["id"],
        type="function",
        function=SimpleNamespace(name=call["name"], arguments=call["arguments"]),
    )


def _apply_recovered(response: Any, content: str, calls: list[dict]) -> Any:
    """Apply recovered content/tool calls to either API response shape."""
    native_calls = [_make_native_tool_call(c) for c in calls]

    # Responses-API middleware adapter (or any object with content/tool_calls).
    if hasattr(response, "tool_calls") and hasattr(response, "content"):
        try:
            response.content = content
            response.tool_calls = native_calls
            return response
        except Exception:
            pass

    # Chat Completions shape. Mutate the original message when possible so
    # later middleware and the kernel's serializer see the recovered call.
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            try:
                msg.content = content
                msg.tool_calls = native_calls
                return response
            except Exception:
                pass
            new_msg = SimpleNamespace(
                role="assistant",
                content=content,
                reasoning_content=getattr(msg, "reasoning_content", "") or "",
                tool_calls=native_calls,
            )
            return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])
    except Exception:
        pass

    # Last resort: assume the object exposes content/tool_calls directly.
    response.content = content
    response.tool_calls = native_calls
    return response


async def after_llm(response, ctx):
    content = _get_content(response)
    existing = _get_tool_calls(response)
    if existing or not content or not content.strip():
        return response

    known_tools = set(getattr(ctx.workspace, "tool_names", []) or [])
    if not re.search(r"DSML", content):
        return response

    recovered = _extract_dsml_calls(content, known_tools, turn=ctx.turn)
    if not recovered:
        # DSML without a recoverable invoke is left for the final-answer
        # guard; do not guess a bare command.
        return response

    content = _strip_dsml_blocks(content)
    ctx.trace.event(
        "text_tool_call_recovered",
        turn=ctx.turn,
        n_calls=len(recovered),
        remaining_content=content,
    )
    return _apply_recovered(response, content, recovered)


async def before_final(answer, ctx):
    text = (answer or "").lower()
    if not any(marker.lower() in text for marker in _TOOL_CALL_TEXT_MARKERS):
        return None

    return {
        "action": "continue",
        "feedback": (
            "Your final message contains tool-call or DSML markup, which does "
            "not execute from message text. If you still need to run a tool, "
            "issue a real tool call now. Otherwise, return only the plain-text "
            "final answer."
        ),
    }

texts.530f8044fe12c655f4109c0cd17fc8dce4edc10d:
"""Supervisor completion gate for AppWorld runs.

This is one execution-layer mechanism with three hooks that keep the agent
honest about finalization:

* ``before_tool`` inspects shell commands that call
  ``apis.supervisor.complete_task``. Action tasks must not pass a descriptive
  ``answer`` (the documented protocol requires the default ``None``), and
  question tasks must pass a concise canonical answer rather than prose or no
  answer at all. Invalid calls are skipped before execution and the model gets
  a bounded, actionable correction.

* ``after_tool`` records a *successful* completion call (the supervisor output
  contains ``Marked the active task complete.`` or ``"task_completed": true``).

* ``before_final`` refuses plain-text final answers until a successful
  completion call has been observed for AppWorld runs, and also rejects
  unexecuted DSML/shell-command text that the model emitted as message content.

The gate keys on the supervisor API name and task wording; it does not know any
task ID or expected answer.
"""

from __future__ import annotations

import re

_DSML_MARKERS = (
    "<｜｜DSML｜｜",
    "<|DSML|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
    "<invoke",
)

_COMPLETE_CALL_RE = re.compile(r"\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_QUESTION_ANSWER_CHARS = 120
_MAX_SKIPS = 3


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question


def _task_instruction(question: str) -> str:
    question = (question or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(question: str) -> bool:
    instruction = _task_instruction(question)
    if not instruction:
        return False
    if instruction.endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _iter_complete_calls(command: str):
    """Yield each ``...complete_task(...)`` call text found in ``command``."""
    for m in _COMPLETE_CALL_RE.finditer(command):
        start = m.end() - 1  # position of '('
        depth = 0
        j = start
        quote = None
        escaped = False
        while j < len(command):
            ch = command[j]
            if quote is not None:
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == quote:
                    quote = None
            else:
                if ch in ("'", '"'):
                    quote = ch
                elif ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        yield command[m.start() : j + 1]
                        break
            j += 1


def _extract_quoted(s: str, quote: str) -> tuple[str, int]:
    """Return (raw_content_without_outer_quotes, end_index_after_closing_quote)."""
    buf: list[str] = []
    i = 0
    escaped = False
    while i < len(s):
        ch = s[i]
        if escaped:
            buf.append(ch)
            escaped = False
        elif ch == "\\":
            buf.append(ch)
            escaped = True
        elif ch == quote:
            return "".join(buf), i + 1
        else:
            buf.append(ch)
        i += 1
    return "".join(buf), 0


def _answer_info(call_text: str) -> dict:
    """Return info about the ``answer`` keyword inside one complete_task call."""
    if "(" not in call_text:
        return {"provided": False}
    inner = call_text[call_text.find("(") + 1 : -1]

    if re.search(r"\banswer\s*=\s*(None|null)\b", inner):
        return {"provided": True, "kind": "none"}

    m = re.search(r"\banswer\s*=\s*([\"'])", inner)
    if m:
        quote = m.group(1)
        value, _ = _extract_quoted(inner[m.end() :], quote)
        return {"provided": True, "kind": "string", "value": value}

    m = re.search(r"\banswer\s*=\s*(-?\d+(?:\.\d+)?)", inner)
    if m:
        return {"provided": True, "kind": "number", "value": m.group(1)}

    if re.search(r"\banswer\s*=", inner):
        return {"provided": True, "kind": "other", "value": ""}

    return {"provided": False}


def _looks_like_prose_answer(value: str | None) -> bool:
    text = (value or "").strip()
    if not text:
        return True
    if "\n" in text or "\r" in text:
        return True
    if len(text) > _MAX_QUESTION_ANSWER_CHARS:
        return True
    low = text.lower()
    if low.startswith(("answer:", "**answer:", "the answer is", "task complete", "task:")):
        return True
    if " — " in text or "|" in text or ";" in text:
        return True
    if re.match(r"^[-*#>]", text):
        return True
    return False


def _looks_like_unexecuted_markup(text: str) -> bool:
    low = (text or "").lower()
    return any(marker.lower() in low for marker in _DSML_MARKERS)


def _looks_like_unexecuted_command(text: str) -> bool:
    stripped = (text or "").strip()
    if not stripped:
        return False
    first_line = stripped.splitlines()[0].strip()
    if first_line.startswith(
        (
            "cd /opt/flashrsi-lite",
            "/opt/flashrsi-lite",
            "print(apis.",
            "apis.",
            "python /opt/flashrsi-lite",
        )
    ):
        return True
    if "appworld_client.py execute" in first_line:
        return True
    return False


def _completion_succeeded(result: str) -> bool:
    if "Marked the active task complete." in result:
        return True
    compact = result.replace("\\", "")
    return '"task_completed": true' in compact or '"task_completed":true' in compact


def _task_completed(ctx) -> bool:
    state = ctx.state.setdefault("finalization_gate", {})
    return bool(state.get("task_completed"))


async def before_tool(name: str, args: dict, ctx):
    if name != "shell" or not _is_appworld(ctx):
        return None

    command = _get_command(args)
    if ".complete_task" not in command:
        return None

    calls = list(_iter_complete_calls(command))
    if not calls:
        return None

    is_question = _is_question_task(ctx.question)
    state = ctx.state.setdefault("finalization_gate", {})

    for call_text in calls:
        info = _answer_info(call_text)

        if not is_question:
            if info.get("provided") and info.get("kind") != "none":
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: this is a non-question action "
                        "task, so apis.supervisor.complete_task must be called with "
                        "no answer argument (or answer=None). Your shell command was "
                        "NOT executed. Read the complete_task docs and call "
                        "apis.supervisor.complete_task() again without a descriptive answer."
                    ),
                }
        else:
            if not info.get("provided") or info.get("kind") not in {"string", "number"}:
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: this is a question task, so "
                        "apis.supervisor.complete_task must be called with a concise "
                        "answer= value (a number, yes/no, name, title, or short list). "
                        "Your shell command was NOT executed. Submit the exact concise "
                        "answer through the shell tool."
                    ),
                }

            if info.get("kind") == "string" and _looks_like_prose_answer(info.get("value")):
                state["skips"] = state.get("skips", 0) + 1
                if state["skips"] > _MAX_SKIPS or getattr(ctx, "remaining_turns", 100) <= 1:
                    return None
                return {
                    "action": "skip",
                    "result": (
                        "Blocked by finalization_gate: the complete_task answer for a "
                        "question task must be concise and canonical, not prose, a "
                        "breakdown, or markdown. Your shell command was NOT executed. "
                        "Re-read the exact question and submit the short answer value."
                    ),
                }

    return None


async def after_tool(name: str, args: dict, result: str, ctx):
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if ".complete_task" not in command:
        return None
    if _completion_succeeded(result):
        state = ctx.state.setdefault("finalization_gate", {})
        state["task_completed"] = True
        state["skips"] = 0
    return None


async def before_final(answer: str, ctx):
    if not _is_appworld(ctx):
        return None

    text = answer or ""
    if _looks_like_unexecuted_markup(text) or _looks_like_unexecuted_command(text):
        return {
            "action": "continue",
            "feedback": (
                "Your final message contains tool-call markup or a shell command, "
                "which does not execute from message text. If you still need to run "
                "a tool, issue a real shell tool call now. Otherwise, return only the "
                "plain-text final answer."
            ),
        }

    if not _task_completed(ctx):
        return {
            "action": "continue",
            "feedback": (
                "You have not successfully called apis.supervisor.complete_task "
                "through the shell tool for this AppWorld task. Call it now with the "
                "protocol-correct answer: no answer (or answer=None) for an action "
                "task, or the exact concise answer for a question task. Then return a "
                "short final message."
            ),
        }

    return None

texts.5e25c559245704d5ebbfbca4c0bc61ba3d853831:
"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)

# Full tool results are retained for middleware audit use. Shell output is already
# capped at 32 KiB by the shell tool; this bound only stops pathological built-ins
# from making audit prompts unbounded.
_RESULT_FULL_LIMIT = 65536


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_full: str = ""
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


