"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)

# Extra tool-capable turns granted after the configured turn limit so a run
# that is still finishing work (final verification, task-completion call) can
# end cleanly instead of emitting tool-call markup as a final answer.
FINALIZATION_GRACE_TURNS = 3


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    # The configured max_turns is the normal budget; allow a bounded
    # finalization window so the model is not forced to produce a final answer
    # in the middle of pending tool work.
    total_turns = max_turns + FINALIZATION_GRACE_TURNS
    ctx.max_turns = total_turns
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": llm.MAX_TOKENS,
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    for turn in range(1, total_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = llm.MAX_TOKENS
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        is_last_turn = turn == total_turns
        _tc = "none" if is_last_turn else "auto"
        _tools_resp = None if is_last_turn else responses_tools
        _tools_chat = None if is_last_turn else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    resp = await llm.responses(
                        response_history + response_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=_tools_resp,
                        tool_choice=_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                else:
                    resp = await llm.chat(
                        messages, model=model, tools=_tools_chat, tool_choice=_tc
                    )

                if _log_dir is not None:
                    try:
                        _resp_data = (
                            resp.model_dump()
                            if hasattr(resp, "model_dump")
                            else repr(resp)
                        )
                    except Exception:
                        _resp_data = repr(resp)
                    _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                    trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                _llm_last_err = None
                break  # success

            except Exception as e:
                _llm_last_err = e
                logger.warning(
                    "LLM call failed (turn %d, attempt %d/%d): %s",
                    turn,
                    _attempt,
                    llm.LLM_MAX_RETRIES,
                    trace.redact(str(e)),
                )
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)  # 2s, 4s

        if _llm_last_err is not None:
            e = _llm_last_err
            http_detail = {}
            for key in ("status_code", "llm_provider", "model"):
                val = getattr(e, key, None)
                if val is not None:
                    http_detail[key] = val
            cur = e
            while cur is not None:
                http_resp = getattr(cur, "response", None)
                if http_resp is not None and hasattr(http_resp, "status_code"):
                    http_detail["status"] = getattr(http_resp, "status_code", None)
                    http_detail["url"] = str(getattr(http_resp, "url", ""))
                    http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                    try:
                        http_detail["body"] = http_resp.text
                    except Exception:
                        http_detail["body"] = repr(getattr(http_resp, "content", b""))
                    break
                cur = getattr(cur, "original_exception", None) or getattr(
                    cur, "__cause__", None
                )
            logger.warning(
                "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                _attempt,
                turn,
                trace.redact(str(e)),
                trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
            )
            stop_reason = f"llm_error: {e}"
            break

        usage = {
            "role": "primary",
            "turn": turn,
            "model": model,
            "call_id": getattr(resp, "id", None),
            "latency_seconds": time.monotonic() - request_started,
            "usage": llm.usage_dict(resp),
        }
        ctx.model_usage.append(usage)
        trace.event("model_usage", **usage)
        failure = llm.response_error(resp, responses_api=use_responses_api)
        if failure:
            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            messages.append({"role": "assistant", "content": final_answer})
            if final_action == "continue" and feedback:
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            answer = final_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            try:
                result = await _dispatch(name, args, ctx)
            except Exception as e:
                result = f"tool error: {e}"
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": result,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                f"Tool: {name}\n"
                                f"Arguments: {json.dumps(args, ensure_ascii=False)}\n"
                                f"Result:\n{result}"
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            try:
                inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    f"Tool: {inj_name}\n"
                    f"Arguments: {json.dumps(inj_args, ensure_ascii=False)}\n"
                    f"Result:\n{inj_result}"
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    _tool_markup_re = re.compile(
        r"<[^>]*(?:"
        r"DSML[^>]*(?:calls|invoke|parameter)|"
        r"tool_calls|function_calls|"
        r"invoke\s+name=|parameter\s+name="
        r")",
        re.IGNORECASE,
    )

    def _clean_answer(text: str) -> str:
        """Strip tool-call markup a model may have emitted as message text."""
        if not text:
            return text
        match = _tool_markup_re.search(text)
        if match:
            return text[: match.start()].strip()
        return text.strip()

    answer_had_tool_markup = bool(answer and _tool_markup_re.search(answer))
    answer = _clean_answer(answer)
    if answer_had_tool_markup:
        # Tool-call markup is not a final answer. Discard it so the forced
        # plain-text fallback below runs.
        answer = ""

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages, model=model, tools=None, tool_choice="none"
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    answer = forced
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

texts.94fb6683910f7ff114aa8a90002668d30db69c57:
"""Deterministic pre-completion semantic guards.

Before a ``supervisor.complete_task`` call is allowed to run, cheap
deterministic checks catch clear violations of task wording in the executed
shell history. These run before the side-LLM audit and are intentionally narrow:

* relationship sets must be resolved from the authoritative phone-contact
  source when the task names friends/roommates/coworkers/siblings/relatives;
* Spotify song/album library tasks must be read from ``show_song_library`` /
  ``show_album_library`` rather than ``show_liked_songs`` / ``show_liked_albums``;
* a playlist creation must not leave ``is_public`` to the API default; and
* a "most-liked" question must verify the private, user-specific liked signal
  rather than only the public like count.
* a paginated list query that returned a full page must be followed by later
  ``page_index`` pagination before completion; and
* when a task asks for "songs in my playlists which I have liked",
  ``show_liked_playlists`` output is a playlist list, not the target song set,
  so a tool-result nudge reminds the model to intersect liked songs with owned
  playlist songs.

Each guard is bounded: after ``_MAX_SKIPS`` skips in a run, or on the final
usable tool turn, the completion call is allowed through so a run can still
finish. Guards are skipped for non-AppWorld tasks.
"""

from __future__ import annotations

import re

_COMPLETION_CALL_RE = re.compile(r"\.complete_task\s*\(")
_RELATIONSHIP_WORDS = ("friend", "roommate", "coworker", "sibling", "relative")
_PHONE_SOURCE_CALLS = (
    "search_contacts(",
    "show_contact_relationships(",
)
_VENMO_SOCIAL_CALLS = (
    "search_friends(",
)
_PRIVATE_LIKED_CALLS = (
    "show_liked_songs(",
    "show_song_privates(",
    "show_album_privates(",
)
_SONG_LIBRARY_CALL = "show_song_library"
_ALBUM_LIBRARY_CALL = "show_album_library"
_LIKED_SONGS_CALL = "show_liked_songs"
_LIKED_ALBUMS_CALL = "show_liked_albums"
_PLAYLIST_CREATION_WORDS = ("create", "new", "add")
_MAX_SKIPS = 3
_MAX_LIKED_PLAYLIST_NUDGES = 2
_MAX_LIBRARY_NUDGES = 2

_SPOTIFY_CLEANUP_WORDS = ("cleanup", "clean up", "keep only", "remove the rest")
_SPOTIFY_REMOVE_CALLS = (
    "remove_song_from_library(",
    "remove_album_from_library(",
)

_PAGE_LIMIT_RE = re.compile(r"page_limit\s*=\s*(\d+)")
_LIST_ITEM_FIELDS = (
    "transaction_id",
    "email_thread_id",
    "song_id",
    "playlist_id",
    "contact_id",
    "text_message_id",
    "album_id",
    "artist_id",
)
_LIKED_SONGS_IN_PLAYLISTS_RE = re.compile(
    r"songs?\s+in\s+my\s+(?:spotify\s+)?playlists?\s+(?:which|that)\s+i\s+have\s+liked",
    re.IGNORECASE,
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _task_instruction(question: str) -> str:
    """Return the first paragraph, which is normally the task itself."""
    question = (question or "").strip()
    idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "appworld_client.py" in question or "Supervisor:" in question


def _executed_commands(ctx) -> list[str]:
    """Return commands from executed shell tool calls, most recent last."""
    commands: list[str] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            commands.append(command)
    return commands


def _executed_records(ctx) -> list[tuple[int, str, str]]:
    """Return ``(seq, command, result)`` for executed shell calls."""
    records: list[tuple[int, str, str]] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if not command:
            continue
        result = (
            getattr(rec, "result_full", None)
            or getattr(rec, "result_preview", "")
            or ""
        )
        records.append((rec.seq, command, result))
    return records


def _has(commands: list[str], needles) -> bool:
    return any(needle in command for command in commands for needle in needles)


def _has_call(commands: list[str], func_name: str) -> bool:
    """True when ``func_name`` is called with a ``(`` in any command."""
    pattern = re.compile(re.escape(func_name) + r"\s*\(")
    return any(pattern.search(command) for command in commands)


def _iter_call_args(command: str, func_name: str):
    """Yield the balanced argument text for each ``func_name(...)`` call."""
    marker = func_name + "("
    idx = 0
    while True:
        idx = command.find(marker, idx)
        if idx < 0:
            break
        start = idx + len(marker)
        depth = 1
        i = start
        quote: str | None = None
        escaped = False
        while i < len(command) and depth > 0:
            char = command[i]
            if quote is not None:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
            else:
                if char in ("'", '"'):
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
            i += 1
        if depth == 0:
            yield command[start : i - 1]
        idx = i


def _has_create_playlist_without_visibility(commands: list[str]) -> bool:
    for command in commands:
        if "create_playlist(" not in command:
            continue
        for args in _iter_call_args(command, "create_playlist"):
            if "is_public" not in args:
                return True
    return False


def _library_needs(instruction: str) -> tuple[bool, bool]:
    """Return ``(needs_song_library, needs_album_library)`` for a task wording."""
    instruction = instruction.lower()
    need_song = "song library" in instruction
    need_album = "album library" in instruction
    if "song and album library" in instruction:
        need_song = need_album = True
    return need_song, need_album


def _library_source_violation(instruction: str, commands: list[str]) -> str | None:
    """Return a message when a library task used liked-* APIs instead of library APIs.

    AppWorld has separate ``show_song_library``/``show_album_library`` and
    ``show_liked_songs``/``show_liked_albums`` endpoints. A task that names the
    user's song or album library must be derived from the library endpoint; the
    liked-* collections are a different, smaller set and produce verifier
    failures when used as a substitute.
    """
    need_song, need_album = _library_needs(instruction)

    wrong: list[str] = []
    if (
        need_song
        and not _has_call(commands, _SONG_LIBRARY_CALL)
        and _has_call(commands, _LIKED_SONGS_CALL)
    ):
        wrong.append("song library")
    if (
        need_album
        and not _has_call(commands, _ALBUM_LIBRARY_CALL)
        and _has_call(commands, _LIKED_ALBUMS_CALL)
    ):
        wrong.append("album library")

    if not wrong:
        return None

    label = " and ".join(wrong)
    return (
        f"the task refers to the Spotify {label}, but the executed history queried "
        "show_liked_songs/show_liked_albums and never queried the library API(s). "
        "Re-read the correct library with apis.spotify.show_song_library / "
        "apis.spotify.show_album_library, then re-derive and verify the target set "
        "before completing."
    )


def _library_source_nudge(ctx, command: str) -> str | None:
    """Nudge immediately when a liked-* API is fetched for a library task."""
    need_song, need_album = _library_needs(_task_instruction(ctx.question))
    if not (need_song or need_album):
        return None

    previous_commands = _executed_commands(ctx)
    all_commands = previous_commands + [command]

    notes: list[str] = []
    if (
        need_song
        and _has_call([command], _LIKED_SONGS_CALL)
        and not _has_call(all_commands, _SONG_LIBRARY_CALL)
    ):
        notes.append(
            "show_liked_songs returns the songs you have liked, not your Spotify "
            "song library. Use apis.spotify.show_song_library for song-library tasks."
        )
    if (
        need_album
        and _has_call([command], _LIKED_ALBUMS_CALL)
        and not _has_call(all_commands, _ALBUM_LIBRARY_CALL)
    ):
        notes.append(
            "show_liked_albums returns the albums you have liked, not your Spotify "
            "album library. Use apis.spotify.show_album_library for album-library tasks."
        )

    return " ".join(notes) if notes else None


def _block(ctx, state, message: str):
    state["skips"] = state.get("skips", 0) + 1
    # Require a fresh state-read after this feedback before the next retry.
    checkpoint = ctx.state.setdefault("pre_completion_checkpoint", {})
    checkpoint["checkpoint_seq"] = getattr(ctx, "_tool_seq", 0)
    checkpoint["retries"] = 0
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task call by pre_completion_guards: "
            + message
            + " Run the missing verification/fix through the shell tool, then "
            "call supervisor.complete_task again."
        ),
    }


def _page_limit(command: str) -> int | None:
    match = _PAGE_LIMIT_RE.search(command)
    return int(match.group(1)) if match else None


def _count_item_markers(result: str) -> int:
    if not result:
        return 0
    counts = [result.count(field) for field in _LIST_ITEM_FIELDS]
    return max(counts, default=0)


def _is_pagination_followup(command: str) -> bool:
    """True when a command explicitly requests a later page or loops pages."""
    if re.search(r"page_index\s*=\s*[1-9]", command):
        return True
    if (" for " in command or " while " in command) and "page_index" in command:
        return True
    return False


def _has_unpaginated_full_page(ctx) -> bool:
    """True when an executed full page was never followed by later pagination."""
    records = _executed_records(ctx)
    for seq, command, result in records:
        limit = _page_limit(command)
        if not limit:
            continue
        if _count_item_markers(result) < limit:
            continue
        # The command itself may already paginate in a loop.
        if _is_pagination_followup(command):
            continue
        if any(
            later_seq > seq and _is_pagination_followup(later_command)
            for later_seq, later_command, _ in records
        ):
            continue
        return True
    return False


def _is_liked_songs_in_playlists_task(ctx) -> bool:
    instruction = _task_instruction(ctx.question).lower()
    return bool(_LIKED_SONGS_IN_PLAYLISTS_RE.search(instruction))

def _spotify_cleanup_violation(ctx, instruction: str) -> str | None:
    """Return a message when a Spotify library cleanup is completed without
    re-verifying post-removal state.

    The recurring failure is completing after re-listing only the final library
    IDs/counts. The task wording requires the *kept* items to satisfy private
    predicates, so the history must show fresh state-reads after the last
    removal: ``show_song_privates`` for kept songs, ``show_album_privates`` for
    kept albums, and (when playlists are mentioned) ``show_playlist_library``.
    """
    low = instruction.lower()
    if "song and album library" in low:
        needs_song_library = True
        needs_album_library = True
    else:
        needs_song_library = "song library" in low
        needs_album_library = "album library" in low
    if not (needs_song_library and needs_album_library):
        return None
    if not any(word in low for word in _SPOTIFY_CLEANUP_WORDS):
        return None

    records = _executed_records(ctx)
    if not records:
        return None

    last_removal_seq = None
    for seq, command, _ in records:
        if any(call in command for call in _SPOTIFY_REMOVE_CALLS):
            last_removal_seq = seq

    if last_removal_seq is None:
        # Nothing removed yet, so there is no post-removal state to verify.
        return None

    post_commands = [
        command for seq, command, _ in records if seq > last_removal_seq
    ]

    missing: list[str] = []
    if not any("show_song_privates(" in command for command in post_commands):
        missing.append("show_song_privates for each retained song")
    if not any("show_album_privates(" in command for command in post_commands):
        missing.append("show_album_privates for each retained album")
    if "playlist" in low and not any(
        "show_playlist_library(" in command for command in post_commands
    ):
        missing.append("show_playlist_library to confirm playlists are unchanged")

    if not missing:
        return None

    return (
        "this Spotify library cleanup removed songs/albums, but after the last "
        "removal the executed history never re-verified: "
        + "; ".join(missing)
        + ". Run post-removal verification (for retained songs check "
        "show_song_privates liked and downloaded; for retained albums check "
        "show_album_privates liked and every show_album track is downloaded; "
        "compare a pre/post show_playlist_library snapshot) before completing."
    )


async def before_tool(name: str, args: dict, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    if not _COMPLETION_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx):
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    if state.get("skips", 0) >= _MAX_SKIPS:
        return None
    if getattr(ctx, "remaining_turns", 100) <= 1:
        return None

    instruction = _task_instruction(ctx.question).lower()
    commands = _executed_commands(ctx)

    # 1. Relationship set must come from the named authoritative source.
    if any(word in instruction for word in _RELATIONSHIP_WORDS):
        if _has(commands, _VENMO_SOCIAL_CALLS) and not _has(
            commands, _PHONE_SOURCE_CALLS
        ):
            return _block(
                ctx,
                state,
                "this task names a relationship set (friends, roommates, "
                "coworkers, siblings, relatives, etc.), but the executed history "
                "resolved targets from Venmo search_friends and never queried the "
                "authoritative phone contacts. Resolve the set with "
                "apis.phone.search_contacts or "
                "apis.phone.show_contact_relationships, then re-verify coverage.",
            )

    # 2. Spotify song/album library must come from library APIs, not liked-*.
    library_msg = _library_source_violation(instruction, commands)
    if library_msg:
        return _block(ctx, state, library_msg)

    # 3. Playlist visibility must be explicit and verified.
    if any(word in instruction for word in _PLAYLIST_CREATION_WORDS) and "playlist" in instruction:
        if _has_create_playlist_without_visibility(commands):
            return _block(
                ctx,
                state,
                "a playlist was created without an explicit is_public argument, so "
                "visibility was left to the API default. Re-create or update the "
                "playlist with is_public set explicitly (use is_public=True unless "
                "the task explicitly requires a private playlist) and verify the "
                "created playlist's is_public value.",
            )

    # 4. "most-liked" must verify the private liked signal, not only like_count.
    if "most-liked" in instruction or "most liked" in instruction:
        if _has(commands, ("like_count",)) and not _has(
            commands, _PRIVATE_LIKED_CALLS
        ):
            return _block(
                ctx,
                state,
                "the task asks for a 'most-liked' item, but the executed history "
                "used only the public like_count metric. Verify the private, "
                "user-specific liked signal as well (for example "
                "show_liked_songs / show_song_privates / show_album_privates) and "
                "recompute the answer from the reading the task wording supports.",
            )

    # 5. A full page from a paginated list query must be followed by pagination.
    if _has_unpaginated_full_page(ctx):
        return _block(
            ctx,
            state,
            "a paginated list query returned a full page but was never followed "
            "by a later page_index (1,2,...). Paginate the complete window/feed "
            "until a short page is observed, then re-verify coverage before "
            "completing.",
        )

    # 6. A Spotify library cleanup must re-verify post-removal state.
    cleanup_msg = _spotify_cleanup_violation(ctx, instruction)
    if cleanup_msg:
        return _block(ctx, state, cleanup_msg)

    return None


async def after_tool(name: str, args: dict, result: str, ctx):
    """Append bounded nudges when a task-relevant wrong source is fetched."""
    if name != "shell":
        return None
    if not _is_appworld_run(ctx):
        return None

    command = _get_command(args)
    if not command:
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    appended: list[str] = []

    # Nudge when a liked-playlist API is fetched for a liked-songs task.
    if (
        "show_liked_playlists(" in command
        and _is_liked_songs_in_playlists_task(ctx)
    ):
        count = state.get("liked_playlist_nudges", 0)
        if count < _MAX_LIKED_PLAYLIST_NUDGES:
            state["liked_playlist_nudges"] = count + 1
            appended.append(
                "[pre_completion_guards] show_liked_playlists returns the "
                "playlists you have liked, not the songs in your playlists which you "
                "have liked. The target set is show_liked_songs(...) intersected with "
                "the song IDs in your owned playlists (show_playlist / "
                "show_playlist_library). Do not act on liked-playlist songs directly; "
                "verify the intersection before rating or completing."
            )

    # Nudge when a liked-* API is fetched for a song/album library task.
    library_nudge = _library_source_nudge(ctx, command)
    if library_nudge:
        count = state.get("library_nudges", 0)
        if count < _MAX_LIBRARY_NUDGES:
            state["library_nudges"] = count + 1
            appended.append("[pre_completion_guards] " + library_nudge)

    if not appended:
        return None
    return result + "\n\n" + "\n\n".join(appended)

texts.99b4400523e4056c0f12b066b16939c037ded6fe:
"""Deterministic Spotify source guard for AppWorld completion calls.

A reported AppWorld failure is exporting/cleaning/rating the wrong Spotify
source: tasks that name the user's *song library* / *album library* get
implemented with ``show_liked_songs`` / ``show_liked_albums`` instead of the
library endpoints ``show_song_library`` / ``show_album_library``.  The two are
different data, and the resulting state looks self-verified even though the
verifier rejects it.

This ``before_tool`` guard runs before ``supervisor.complete_task`` and blocks
the submission only when:

* the task instruction explicitly names a Spotify source (song/album library,
  liked songs/albums, or playlist library/all playlists), and
* the executed shell history already contains Spotify calls, but none of the
  required endpoints for that source appears.

It is bounded (at most three skips per run), disabled on the final usable tool
turn, and does not know any task ID or expected answer.
"""

from __future__ import annotations

import re

_MAX_SKIPS_PER_RUN = 3
_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    for marker in ("\nSupervisor:", "\n\nSupervisor:"):
        idx = question.find(marker)
        if idx != -1:
            return question[:idx].strip()
    return question


def _executed_commands(ctx):
    for rec in getattr(ctx, "tool_history", []) or []:
        if getattr(rec, "requested_name", None) != "shell":
            continue
        if getattr(rec, "action", "executed") == "skipped":
            continue
        command = _get_command(getattr(rec, "requested_args", None) or {})
        if command:
            yield command


def _required_endpoints(instruction: str) -> list[str]:
    """Return Spotify endpoints that must appear for the named task source."""
    lower = instruction.lower()
    required: list[str] = []

    # "song and album library" is a single phrase where "song library" is not
    # contiguous, so handle it before the individual library checks.
    if "song and album library" in lower:
        required.append("show_song_library")
        required.append("show_album_library")

    if "song library" in lower and "show_song_library" not in required:
        required.append("show_song_library")
    if "album library" in lower and "show_album_library" not in required:
        required.append("show_album_library")
    if "liked song" in lower and "show_liked_songs" not in required:
        required.append("show_liked_songs")
    if "liked album" in lower and "show_liked_albums" not in required:
        required.append("show_liked_albums")
    if ("playlist library" in lower or "all playlists" in lower) and (
        "show_playlist_library" not in required
    ):
        required.append("show_playlist_library")

    return required


def _has_spotify_calls(commands) -> bool:
    return any("apis.spotify." in command for command in commands)


async def before_tool(name: str, args: dict, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx):
        return None

    # Never consume the final usable tool turn on a guard.
    if getattr(ctx, "remaining_turns", 100) <= 1:
        return None

    instruction = _task_instruction(ctx)
    required = _required_endpoints(instruction)
    if not required:
        return None

    commands = list(_executed_commands(ctx))
    if not commands or not _has_spotify_calls(commands):
        return None

    missing = [endpoint for endpoint in required if not any(endpoint in c for c in commands)]
    if not missing:
        return None

    state = ctx.state.setdefault("spotify_source_guard", {})
    if int(state.get("skips", 0)) >= _MAX_SKIPS_PER_RUN:
        return None
    state["skips"] = int(state.get("skips", 0)) + 1
    ctx.trace.event("spotify_source_guard_skip", count=state["skips"])

    missing_text = ", ".join(missing)
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task: the task names a Spotify source "
            f"that must be read with {missing_text}, but the executed history "
            "does not show that endpoint. Re-read the correct source "
            "(song/album library -> apis.spotify.show_song_library / "
            "show_album_library; liked items -> show_liked_songs / "
            "show_liked_albums; playlist library -> show_playlist_library), "
            "then call apis.supervisor.complete_task again."
        ),
    }

texts.9b86ed529c07684d69006ee6c42bf1938f7966a0:
"""Deterministic pre-completion guard for explicit side-effect defaults.

A reported AppWorld failure mode is creating a Spotify playlist without an
explicit ``is_public`` argument: the API defaults to private, but the verifier
requires a public playlist. This guard runs before
``supervisor.complete_task`` for playlist-creation tasks that do not ask for a
private playlist. If the executed history contains a ``create_playlist`` call
and none of the executed calls set ``is_public=True`` explicitly, the
submission is blocked with a precise correction.

The guard is conservative and bounded (at most three skips per run), and keys
only on the task wording and the executed shell history.
"""

from __future__ import annotations

import re

_MAX_SKIPS_PER_RUN = 3
_IS_PUBLIC_RE = re.compile(r"\bis_public\s*=\s*(?:True|1)\b")
_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_playlist_creation_task(ctx) -> bool:
    instruction = _task_instruction(ctx).lower()
    return "playlist" in instruction and "private" not in instruction


def _executed_commands(ctx):
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            yield command


def _has_create_playlist_call(ctx) -> bool:
    return any("create_playlist(" in command for command in _executed_commands(ctx))


def _has_explicit_public_create(ctx) -> bool:
    for command in _executed_commands(ctx):
        if "create_playlist(" in command and _IS_PUBLIC_RE.search(command):
            return True
    return False


def _skip(ctx, state: dict):
    state["skips"] = int(state.get("skips", 0)) + 1
    ctx.trace.event(
        "explicit_defaults_guard_skip",
        count=state["skips"],
    )
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task: the task creates a Spotify "
            "playlist and does not request a private one, but the executed "
            "create_playlist call(s) did not set is_public=True explicitly. "
            "Re-create or correct the playlist with is_public=True, verify its "
            "visibility, then call supervisor.complete_task again."
        ),
    }


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx):
        return None
    if not _is_playlist_creation_task(ctx):
        return None

    state = ctx.state.setdefault("explicit_defaults_guard", {})
    if int(state.get("skips", 0)) >= _MAX_SKIPS_PER_RUN:
        return None

    if not _has_create_playlist_call(ctx):
        return None
    if _has_explicit_public_create(ctx):
        return None

    return _skip(ctx, state)

texts.a079326957c8add6462be0362483f682f3305e9d:
"""Deterministic pre-completion guard for Spotify liked-playlist target sets.

One reported AppWorld failure is rating/reviewing the wrong set for tasks like
"rate all songs in my playlists which I have liked".  The agent computes the
correct intersection and then acts on a larger nearby set, so the verifier
fails even though the final self-check looked fine.

This middleware runs before ``supervisor.complete_task`` for Spotify action
tasks that ask to rate/review songs in playlists filtered by the user's
private liked signal.  It requires the executed shell history to contain:

1. a private liked-library query (``show_liked_songs`` or
   ``show_song_privates``);
2. playlist membership evidence (``show_playlist_library`` or
   ``show_playlist``); and
3. explicit set-intersection evidence (``&`` or ``.intersection(...)``) so the
   final target set is the exact X-filtered-by-Y set rather than a nearby one.

The guard is narrow, conservative, and bounded (at most two skips per run).  It
keys only on the task wording and the executed shell history, never on task IDs
or expected answers.
"""

from __future__ import annotations

import re

_MAX_SKIPS_PER_RUN = 2
_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")

_LIKED_QUERIES = ("show_liked_songs(", "show_song_privates(")
_PLAYLIST_QUERIES = ("show_playlist_library(", "show_playlist(")
_RATING_VERBS = ("rate", "rating", "review")
_LIKED_PHRASES = (
    "which i have liked",
    "that i have liked",
    "liked songs in my playlists",
    "songs in my playlists which i have liked",
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_target_task(ctx) -> bool:
    instruction = _task_instruction(ctx).lower()
    if "spotify" not in instruction and "playlist" not in instruction:
        return False
    if "playlist" not in instruction:
        return False
    if not any(verb in instruction for verb in _RATING_VERBS):
        return False
    return any(phrase in instruction for phrase in _LIKED_PHRASES)


def _executed_commands(ctx):
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            yield command


def _executed_has(ctx, needles) -> bool:
    return any(
        any(needle in command for needle in needles)
        for command in _executed_commands(ctx)
    )


def _has_intersection_evidence(ctx) -> bool:
    for command in _executed_commands(ctx):
        low = command.lower()
        if ".intersection(" in low:
            return True
        if " & " in command:
            return True
    return False


def _skip(ctx, state: dict, feedback: str):
    state["skips"] = int(state.get("skips", 0)) + 1
    ctx.trace.event(
        "spotify_target_guard_skip",
        count=state["skips"],
        reason=feedback.splitlines()[0] if feedback else "",
    )
    return {"action": "skip", "result": feedback}


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx) or not _is_target_task(ctx):
        return None

    state = ctx.state.setdefault("spotify_target_guard", {})
    if int(state.get("skips", 0)) >= _MAX_SKIPS_PER_RUN:
        return None

    if not _executed_has(ctx, _LIKED_QUERIES):
        return _skip(
            ctx,
            state,
            "Blocked supervisor.complete_task: this task rates/reviews songs in "
            "your Spotify playlists that you have liked, but the executed history "
            "does not show a private liked-library query (apis.spotify.show_liked_songs "
            "or apis.spotify.show_song_privates). Pull the user's liked songs first, "
            "then rebuild the target set and resubmit.",
        )

    if not _executed_has(ctx, _PLAYLIST_QUERIES):
        return _skip(
            ctx,
            state,
            "Blocked supervisor.complete_task: this task rates/reviews songs in "
            "your Spotify playlists that you have liked, but the executed history "
            "does not show playlist membership evidence (apis.spotify.show_playlist_library "
            "or apis.spotify.show_playlist). Read the playlist song memberships first, "
            "then rebuild the target set and resubmit.",
        )

    if not _has_intersection_evidence(ctx):
        return _skip(
            ctx,
            state,
            "Blocked supervisor.complete_task: this task asks for songs in your "
            "playlists which you have liked, but the executed history has no explicit "
            "set intersection. Build the exact target set in code, for example "
            "targets = set(liked_song_ids) & set(playlist_song_ids), print it, and act "
            "only on that set. Then re-verify and resubmit.",
        )

    return None

texts.a1761ec04d041521fc99cc280cb4612e7afbc9c1:
"""Deterministic supervisor completion protocol guard.

AppWorld tasks are graded only after the agent submits through
``apis.supervisor.complete_task``, and that call has a strict protocol:

* action tasks must leave ``answer`` at its default ``None``;
* question tasks must pass the exact concise canonical answer;
* the run must not end until a real completion call has succeeded.

The evidence shows otherwise-correct runs losing points because they either
never made the completion call, or made it with a long descriptive ``answer``
on an action task. This middleware enforces the protocol without any task ID
or expected answer:

* ``before_tool`` inspects shell commands that actually call
  ``supervisor.complete_task``. For action tasks it blocks any non-None
  ``answer``; for question tasks it blocks a missing or clearly prose answer.
* ``after_tool`` records a *successful* completion (the supervisor returns
  ``Marked the active task complete.`` / ``"task_completed": true``).
* ``before_final`` continues the turn when an AppWorld run has no recorded
  successful completion, so the run cannot end on prose or an unexecuted
  command without ever reaching the supervisor.

The gate is generic and bounded: each run may block at most three malformed
completions, and ``before_final`` is capped by the runtime's existing
``_final_continue_max`` budget.
"""

from __future__ import annotations

import re

_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_QUESTION_ANSWER_CHARS = 150
_MAX_SKIPS_PER_RUN = 3

_FEEDBACK = (
    "Your final message arrived without a successful supervisor.complete_task "
    "call, so the task has not been submitted for grading. Use a real shell "
    "tool call to execute Python in the AppWorld session, for example:\n"
    "  /opt/flashrsi-lite/venv/bin/python /opt/flashrsi-lite/appworld_client.py "
    "execute <<'PY'\n"
    "  print(apis.supervisor.complete_task())\n"
    "  PY\n"
    "If the task asks for a value, pass the exact concise answer as answer=...; "
    "if it does not ask for a value, omit answer. After the tool result shows "
    "the task is marked complete, return a short plain-text final message."
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(ctx) -> bool:
    instruction = _task_instruction(ctx)
    if not instruction:
        return False
    if instruction.rstrip().endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _split_top_level_args(text: str) -> list[str]:
    """Split ``key=value, key=value`` at top-level commas.

    Respects quotes and nested ``()``, ``[]`` and ``{}`` so string values
    containing commas stay intact.
    """
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    quote: str | None = None
    escaped = False
    for ch in text:
        if quote is not None:
            buf.append(ch)
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
            continue
        if ch in ("'", '"'):
            quote = ch
            buf.append(ch)
            continue
        if ch in "([{":
            depth += 1
            buf.append(ch)
            continue
        if ch in ")]}":
            depth = max(0, depth - 1)
            buf.append(ch)
            continue
        if ch == "," and depth == 0:
            parts.append("".join(buf).strip())
            buf = []
            continue
        buf.append(ch)
    if buf:
        parts.append("".join(buf).strip())
    return parts


def _get_kwarg(text: str, key: str) -> str | None:
    for part in _split_top_level_args(text):
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        if k.strip() == key:
            return v.strip()
    return None


def _extract_complete_call(command: str) -> str | None:
    """Return the first balanced ``supervisor.complete_task(...)`` call text."""
    match = _COMPLETE_CALL_RE.search(command)
    if not match:
        return None
    open_idx = command.find("(", match.start())
    if open_idx < 0:
        return None
    depth = 0
    i = open_idx
    quote: str | None = None
    escaped = False
    while i < len(command):
        ch = command[i]
        if quote is not None:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
        else:
            if ch in ("'", '"'):
                quote = ch
            elif ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return command[match.start() : i + 1]
        i += 1
    return None


def _classify_answer(raw: str | None) -> tuple[str, str | None]:
    """Return (kind, value) for a raw ``answer=...`` argument.

    ``kind`` is one of ``missing``, ``none``, ``string``, or ``other``.
    """
    if raw is None:
        return ("missing", None)
    raw = raw.strip()
    if raw.lower() in ("none", "null"):
        return ("none", None)
    if len(raw) >= 2 and raw[0] in ("'", '"') and raw[-1] == raw[0]:
        return ("string", raw[1:-1])
    return ("other", raw)


def _skip(ctx, state: dict, feedback: str):
    state["skips"] = int(state.get("skips", 0)) + 1
    ctx.trace.event(
        "completion_protocol_skip",
        count=state["skips"],
        reason=feedback.splitlines()[0] if feedback else "",
    )
    return {"action": "skip", "result": feedback}


def _completion_succeeded(result) -> bool:
    if not isinstance(result, str):
        return False
    if "Marked the active task complete." in result:
        return True
    compact = result.replace("\\", "")
    return '"task_completed": true' in compact or '"task_completed":true' in compact


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    call = _extract_complete_call(command)
    if not call:
        return None
    if not _is_appworld_run(ctx):
        return None

    state = ctx.state.setdefault("completion_protocol", {})
    if int(state.get("skips", 0)) >= _MAX_SKIPS_PER_RUN:
        return None

    inner = call[call.find("(") + 1 : -1]
    answer_raw = _get_kwarg(inner, "answer")
    is_question = _is_question_task(ctx)

    if is_question:
        kind, value = _classify_answer(answer_raw)
        if kind in ("missing", "none"):
            return _skip(
                ctx,
                state,
                "Blocked supervisor.complete_task: this is a question task, so "
                "answer=... must contain the exact concise value (a number, "
                "yes/no, a name/title, or a short comma-separated list). "
                "Reissue the call with the correct answer value.",
            )
        if kind == "string" and value is not None:
            if len(value) > _MAX_QUESTION_ANSWER_CHARS or "\n" in value:
                return _skip(
                    ctx,
                    state,
                    "Blocked supervisor.complete_task: the answer looks like "
                    "prose or explanation. Submit only the concise canonical "
                    "value with no markdown or extra prose, then reissue the "
                    "call.",
                )
    else:
        kind, _ = _classify_answer(answer_raw)
        if kind not in ("missing", "none"):
            return _skip(
                ctx,
                state,
                "Blocked supervisor.complete_task: this is an action task, so "
                "answer must be left to the default None. Reissue the call as "
                "apis.supervisor.complete_task() (or complete_task(status="
                "'success')) without an answer=... argument.",
            )

    return None


async def after_tool(name, args, result, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _completion_succeeded(result):
        return None
    state = ctx.state.setdefault("completion_protocol", {})
    state["completed"] = True
    ctx.trace.event("completion_protocol_completed")
    return None


async def before_final(answer, ctx):
    if not _is_appworld_run(ctx):
        return None
    state = ctx.state.setdefault("completion_protocol", {})
    if state.get("completed"):
        return None
    return {
        "action": "continue",
        "feedback": _FEEDBACK,
    }

texts.ae50271565a74ed59e12919f459daf4eb205f451:
"""Reusable AppWorld recommendation-result ordering note.

Question tasks that ask for a *most/least recommended* item over a
recommendation feed are answered from the feed's returned order, not by
tallying how often an entity appears.  This ``after_tool`` hook adds a short
reminder immediately after a recommendation/ordered-list result is printed, so
the model sees the semantic rule at the point where it is most likely to
misread the result.

The hook is deliberately narrow and non-authoritative:

* only AppWorld ``shell`` calls that run ``appworld_client.py execute`` are
  considered;
* only tasks whose instruction contains the word ``recommended`` are
  considered;
* only results that look like an ordered/numbered list are annotated; and
* the annotation is appended as a note, never replacing the tool output.
"""

from __future__ import annotations

import re
from typing import Any

_EXECUTE_MARKER = "appworld_client.py execute"

_ORDERED_LINE_RE = re.compile(r"^\s*(\d+)\s+(.+)$", re.MULTILINE)


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "AppWorld tools are available" in question:
        return True
    return (
        "Supervisor:" in question
        and "Current simulated datetime:" in question
    )


def _get_command(args: Any) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _task_instruction(question: str) -> str:
    question = (question or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    if idx != -1:
        question = question[:idx]
    return question.strip()


def _looks_like_ordered_result(text: str) -> bool:
    lines = [ln for ln in text.splitlines() if ln.strip()]
    if len(lines) < 2:
        return False
    matches = 0
    for ln in lines[:50]:
        match = _ORDERED_LINE_RE.match(ln)
        if not match:
            continue
        rest = match.group(2).strip()
        # Skip page-count lines such as ``0 20`` and ID-list summaries such as
        # ``0 28 [1, 3, ...]``; they are not the item list itself.
        if not rest or rest.isdigit():
            continue
        if rest.startswith("["):
            continue
        matches += 1
    return matches >= 2


async def after_tool(name: str, args: dict, result: Any, ctx) -> Any:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if not command or _EXECUTE_MARKER not in command:
        return None
    if not isinstance(result, str) or not result.strip():
        return None

    instruction = _task_instruction(ctx.question or "")
    if not instruction or "recommended" not in instruction.lower():
        return None
    if "most" not in instruction.lower() and "least" not in instruction.lower():
        return None
    if not _looks_like_ordered_result(result):
        return None

    note = (
        "\n\n[ordered_result] This is an ordered recommendation result. "
        "Answer \"most recommended\" from the first item and "
        "\"least recommended\" from the last item in the returned order. "
        "Do not count occurrences unless the task explicitly asks for a frequency."
    )
    if note in result:
        return None
    return {"result": result + note}

texts.b2b89f2010dc95cce10f1a01e5d9586c13e63912:
"""Completion autopilot for AppWorld action tasks.

One recurring AppWorld failure is the agent finishing its work and then
returning a plain-text summary without ever calling
``apis.supervisor.complete_task``.  The prose is treated as the final answer,
the supervisor is never told the task is complete, and the run is graded as a
failure even though the side effects were performed.

This middleware runs ``after_llm``.  For an AppWorld *action* task that has
already used the AppWorld session and has not yet recorded a successful
completion call, it converts the first plain-text final candidate into a
native ``shell`` tool call that executes ``apis.supervisor.complete_task()``.
That injected call then passes through the normal completion guards
(``completion_protocol`` and ``pre_completion_check``), so a premature or
unverified submission is still blocked and the model is told what to verify.

The autopilot is deliberately narrow and bounded:

* it never fires for question tasks (those need a specific ``answer=...``);
* it never fires when a completion call already succeeded;
* it never fires on DSML/tool-call markup (``recover_tool_calls`` handles it);
* it injects at most once per run and records an explicit trace event.
"""

from __future__ import annotations

import json
import re
from types import SimpleNamespace
from typing import Any

_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")
_QUESTION_LEAD_WORDS = {"what", "which", "when", "where", "who", "why", "how"}
_MAX_INJECTIONS_PER_RUN = 1

_INJECT_COMMAND = (
    "/opt/flashrsi-lite/venv/bin/python /opt/flashrsi-lite/appworld_client.py "
    "execute <<'PY'\n"
    "print(apis.supervisor.complete_task())\n"
    "PY"
)

_TOOL_CALL_TEXT_MARKERS = (
    "<|dsml|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
    "<｜｜dsml｜｜",
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_question_task(ctx) -> bool:
    instruction = _task_instruction(ctx)
    if not instruction:
        return False
    if instruction.rstrip().endswith("?"):
        return True
    first = instruction.split()[0].lower().rstrip(".:") if instruction.split() else ""
    return first in _QUESTION_LEAD_WORDS


def _completion_succeeded(result) -> bool:
    if not isinstance(result, str):
        return False
    if "Marked the active task complete." in result:
        return True
    compact = result.replace("\\", "")
    return '"task_completed": true' in compact or '"task_completed":true' in compact


def _used_appworld(ctx) -> bool:
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        command = _get_command(rec.requested_args)
        if "appworld_client.py" in command or "apis." in command:
            return True
    return False


def _get_content(response: Any) -> str:
    """Best-effort extraction of assistant text from either API shape."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return getattr(msg, "content", "") or ""
    except Exception:
        pass
    return getattr(response, "content", "") or ""


def _get_tool_calls(response: Any) -> list:
    """Return existing native tool calls without mutating anything."""
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            return list(getattr(msg, "tool_calls", None) or [])
    except Exception:
        pass
    return list(getattr(response, "tool_calls", None) or [])


def _make_native_tool_call(call: dict) -> SimpleNamespace:
    return SimpleNamespace(
        id=call["id"],
        type="function",
        function=SimpleNamespace(name=call["name"], arguments=call["arguments"]),
    )


def _apply_injected(response: Any, call: dict) -> Any:
    """Attach one native tool call to either API response shape."""
    native = _make_native_tool_call(call)

    # Responses-API middleware adapter (or any object with content/tool_calls).
    if hasattr(response, "tool_calls") and hasattr(response, "content"):
        try:
            response.tool_calls = [native]
            return response
        except Exception:
            pass

    # Chat Completions shape. Mutate the original message when possible so
    # later middleware and the runtime serializer see the injected call.
    try:
        choices = getattr(response, "choices", None)
        if choices:
            msg = choices[0].message
            try:
                msg.tool_calls = [native]
                return response
            except Exception:
                pass
            new_msg = SimpleNamespace(
                role="assistant",
                content=getattr(msg, "content", "") or "",
                reasoning_content=getattr(msg, "reasoning_content", "") or "",
                tool_calls=[native],
            )
            return SimpleNamespace(choices=[SimpleNamespace(message=new_msg)])
    except Exception:
        pass

    # Last resort: assume the object exposes content/tool_calls directly.
    response.tool_calls = [native]
    return response


async def after_tool(name, args, result, ctx):
    """Record a successful supervisor.complete_task call for our own state."""
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _completion_succeeded(result):
        return None
    state = ctx.state.setdefault("completion_autopilot", {})
    state["completed"] = True
    ctx.trace.event("completion_autopilot_completed")
    return None


async def after_llm(response, ctx):
    if not _is_appworld_run(ctx):
        return response

    state = ctx.state.setdefault("completion_autopilot", {})
    if state.get("completed"):
        return response
    if int(state.get("injections", 0)) >= _MAX_INJECTIONS_PER_RUN:
        return response

    existing = _get_tool_calls(response)
    if existing:
        return response

    content = _get_content(response)
    if not content or not content.strip():
        return response

    low = content.lower()
    if any(marker in low for marker in _TOOL_CALL_TEXT_MARKERS):
        return response

    # Question tasks require a specific answer value; never auto-submit those.
    if _is_question_task(ctx):
        return response

    # Only act when the agent has actually been working in the AppWorld
    # session.  This avoids injecting a completion call into unrelated runs.
    if not _used_appworld(ctx):
        return response

    state["injections"] = int(state.get("injections", 0)) + 1
    call = {
        "id": f"autopilot_{ctx.turn}_{state['injections']}",
        "name": "shell",
        "arguments": json.dumps({"command": _INJECT_COMMAND}, ensure_ascii=False),
    }
    ctx.trace.event(
        "completion_autopilot_inject",
        turn=ctx.turn,
        count=state["injections"],
    )
    return _apply_injected(response, call)

texts.b4ddbc57a78949704f2d6fc9c31b10c9d65fc802:
"""Deterministic pre-completion guard for Venmo target-set failures.

For AppWorld tasks that act on Venmo transactions/payments, the two recurring
failure causes are:

1. resolving a named relationship set (friends, roommates, siblings, ...) from
   the Venmo social graph instead of the authoritative phone contacts; and
2. acting on the first page of a time-windowed ``show_transactions`` /
   ``show_social_feed`` call without paginating to an empty or short page.

This middleware runs when the agent is about to call
``supervisor.complete_task``:

* if the executed history used ``venmo.search_friends`` for a relationship
  task and never queried phone contacts, the submission is blocked; and
* if a Venmo feed/transaction call returned a full page (``page_limit`` items)
  and there is no later evidence of pagination, the submission is blocked.

Pagination evidence is now accepted either as an explicit pagination loop in
the executed command or as a later Venmo feed/transaction result with fewer
than ``page_limit`` items (the normal short/empty terminal page). This catches
the reported failure mode without requiring the model to restructure its
already-correct pagination into a loop.

Both checks are conservative and bounded (at most three skips per run). They
do not look at task IDs or expected answers, only at the task wording and the
executed shell history.
"""

from __future__ import annotations

import re

_MAX_SKIPS_PER_RUN = 3
_MAX_COMMAND_CHARS = 2000
_MAX_PAGES = 12

_RELATIONSHIP_WORDS = (
    "friend",
    "roommate",
    "coworker",
    "sibling",
    "brother",
    "sister",
    "relative",
)
_TIME_WINDOW_WORDS = (
    "venmo",
    "payment",
    "payments",
    "transaction",
    "transactions",
    "received",
    "sent",
    "yesterday",
    "last",
    "since",
)
_PHONE_SOURCE_CALLS = (
    "apis.phone.search_contacts(",
    "apis.phone.show_contact_relationships(",
)
_VENMO_SOURCE_CALLS = ("apis.venmo.search_friends(", "venmo.search_friends(")
_VENMO_TX_CALLS = ("show_transactions(", "show_social_feed(")
_PAGE_LIMIT_RE = re.compile(r"\bpage_limit\s*=\s*(\d+)")
_PAGE_INDEX_RE = re.compile(r"\bpage_index\s*=\s*(\d+)")
_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "Supervisor:" in question or "appworld_client.py" in question


def _task_instruction(ctx) -> str:
    question = (getattr(ctx, "question", "") or "").strip()
    idx = question.find("\n\nSupervisor:")
    if idx == -1:
        idx = question.find("\n\nAppWorld tools")
    if idx == -1:
        idx = question.find("\nSupervisor:")
    return (question[:idx] if idx != -1 else question).strip()


def _is_relationship_task(ctx) -> bool:
    instruction = _task_instruction(ctx).lower()
    return any(word in instruction for word in _RELATIONSHIP_WORDS)


def _is_venmo_task(ctx) -> bool:
    instruction = _task_instruction(ctx).lower()
    return "venmo" in instruction and any(
        word in instruction for word in _TIME_WINDOW_WORDS
    )


def _executed_commands(ctx):
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            yield command


def _executed_has(ctx, needles) -> bool:
    for command in _executed_commands(ctx):
        if any(needle in command for needle in needles):
            return True
    return False


def _command_paginates(command: str) -> bool:
    low = command.lower()
    if "page_index" not in low:
        return False
    if "while true" in low:
        return True
    return "for " in low and "range(" in low


def _has_pagination_loop(ctx) -> bool:
    for command in _executed_commands(ctx):
        if any(api in command for api in _VENMO_TX_CALLS):
            if _command_paginates(command):
                return True
    return False


def _has_pagination_evidence(ctx, state: dict) -> bool:
    if _has_pagination_loop(ctx):
        return True
    return bool(state.get("short_pages"))


def _skip(ctx, state: dict, feedback: str):
    state["skips"] = int(state.get("skips", 0)) + 1
    ctx.trace.event(
        "transaction_target_guard_skip",
        count=state["skips"],
        reason=feedback.splitlines()[0] if feedback else "",
    )
    return {"action": "skip", "result": feedback}


async def after_tool(name, args, result, ctx):
    """Record Venmo feed/transaction calls that returned a full or short page."""
    if name != "shell":
        return None
    command = _get_command(args)
    if not any(api in command for api in _VENMO_TX_CALLS):
        return None
    page_match = _PAGE_LIMIT_RE.search(command)
    if not page_match:
        return None
    page_limit = int(page_match.group(1))
    if page_limit <= 0:
        return None
    if not isinstance(result, str):
        return None

    page_index_match = _PAGE_INDEX_RE.search(command)
    page_index = int(page_index_match.group(1)) if page_index_match else 0

    item_count = result.count("transaction_id")
    if item_count >= page_limit:
        page_kind = "full"
    else:
        page_kind = "short"

    state = ctx.state.setdefault("transaction_target_guard", {})
    if page_kind == "full":
        pages = state.setdefault("full_pages", [])
    else:
        pages = state.setdefault("short_pages", [])
    pages.append(
        {
            "seq": len(getattr(ctx, "tool_history", []) or []),
            "item_count": item_count,
            "page_limit": page_limit,
            "page_index": page_index,
            "command": command[:_MAX_COMMAND_CHARS],
        }
    )
    if len(pages) > _MAX_PAGES:
        pages = pages[-_MAX_PAGES:]
        if page_kind == "full":
            state["full_pages"] = pages
        else:
            state["short_pages"] = pages
    return None


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if not _COMPLETE_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx) or not _is_venmo_task(ctx):
        return None

    state = ctx.state.setdefault("transaction_target_guard", {})
    if int(state.get("skips", 0)) >= _MAX_SKIPS_PER_RUN:
        return None

    # 1. Relationship set must come from phone contacts, not Venmo's graph.
    if _is_relationship_task(ctx):
        if _executed_has(ctx, _VENMO_SOURCE_CALLS) and not _executed_has(
            ctx, _PHONE_SOURCE_CALLS
        ):
            return _skip(
                ctx,
                state,
                "Blocked supervisor.complete_task: this task names a "
                "relationship set (friends, roommates, siblings, etc.), but the "
                "executed history resolved it with Venmo search_friends and "
                "never queried the authoritative phone contacts. Resolve the "
                "set with apis.phone.search_contacts or "
                "apis.phone.show_contact_relationships, re-run the target-set "
                "query, then call supervisor.complete_task again.",
            )

    # 2. A full Venmo page was observed without any pagination evidence.
    full_pages = state.get("full_pages") or []
    if full_pages and not _has_pagination_evidence(ctx, state):
        return _skip(
            ctx,
            state,
            "Blocked supervisor.complete_task: a Venmo transaction/feed call "
            "returned a full page (page_limit items), but there is no evidence "
            "the complete window was paginated. Continue calling "
            "show_transactions/show_social_feed with page_index=1,2,... until "
            "an empty or short page, rebuild the full target set from the "
            "complete window, then re-verify and call supervisor.complete_task "
            "again.",
        )

    return None

texts.b668ad96a8663fb83ed168c22916460abed5cd61:
"""Deterministic pre-completion guard for explicit side-effect parameters.

Some AppWorld side effects fail because the agent leaves API defaults in place
when the task requires a specific state. The cheap deterministic case handled
here is Spotify playlist creation: for a new playlist the executed
``create_playlist`` call must have set ``is_public=True`` explicitly unless the
task itself says the playlist should be private. Relying on the private default
is a reported failure mode.
"""

from __future__ import annotations

import re

_IS_PUBLIC_RE = re.compile(r"is_public\s*=\s*(?:True|1)\b")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "appworld_client.py" in question or "Supervisor:" in question


def _should_require_public(ctx) -> bool:
    """New playlists must be public unless the task explicitly says private."""
    question = (getattr(ctx, "question", "") or "").lower()
    return "playlist" in question and "private" not in question


def _create_playlist_calls(ctx):
    calls = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if "create_playlist(" in command:
            calls.append(rec)
    return calls


def _has_explicit_public_create(ctx) -> bool:
    for rec in _create_playlist_calls(ctx):
        command = _get_command(rec.requested_args)
        if _IS_PUBLIC_RE.search(command):
            return True
    return False


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if "complete_task" not in command:
        return None
    if not _is_appworld_run(ctx):
        return None
    if not _should_require_public(ctx):
        return None

    create_calls = _create_playlist_calls(ctx)
    if not create_calls:
        return None
    if _has_explicit_public_create(ctx):
        return None

    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task call: the task creates a Spotify "
            "playlist and does not request a private one, but the executed "
            "create_playlist call(s) did not set is_public=True explicitly. "
            "Re-create or correct the playlist with is_public=True, verify its "
            "visibility, then call supervisor.complete_task again."
        ),
    }

texts.b8142fe4438b240d4c9a53d7d10c49eb3f2f1305:
"""AppWorld mutation guard for Venmo payment requests.

A trace-visible AppWorld failure occurs when the agent calls
``apis.venmo.add_friend`` immediately before
``apis.venmo.create_payment_request`` even though the payment-request API docs
list no friendship precondition: the receiver is simply an email address.
The extra friend-list mutation changes state that the task never requested,
and state-based verifiers reject the run even when the payment requests
themselves are correct.

This ``before_tool`` hook keeps the mutation from executing:

* it only fires for AppWorld ``shell`` calls containing
  ``appworld_client.py execute``;
* it only fires when the same Python code contains both
  ``apis.venmo.add_friend`` and ``apis.venmo.create_payment_request``;
* it allows the command through when the task text itself asks to add a
  friend;
* it blocks at most twice per run, then lets a later attempt through so a
  legitimate (but unusual) command cannot be blocked forever.  The runtime
  also enforces its own turn limit.
"""

from __future__ import annotations

import ast
import re
from typing import Any

_EXECUTE_MARKER = "appworld_client.py execute"
_HEREDOC_BODY_RE = re.compile(
    r"<<\s*['\"]?PY['\"]?\s*\r?\n(?P<code>.*?)\r?\n\s*PY\s*",
    re.IGNORECASE | re.DOTALL,
)
_FRIEND_ADD_RE = re.compile(r"\badd\b[^.\n]{0,80}\bfriend\b", re.IGNORECASE)


def _is_appworld(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "AppWorld tools are available" in question:
        return True
    return (
        "Supervisor:" in question
        and "Current simulated datetime:" in question
    )


def _instruction(question: str) -> str:
    question = question.strip()
    idx = question.find("\n\nSupervisor:")
    if idx != -1:
        question = question[:idx]
    return question.strip()


def _get_command(args: Any) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _state(ctx) -> dict:
    state = ctx.state.get("appworld_mutation_guard")
    if not isinstance(state, dict):
        state = {}
        ctx.state["appworld_mutation_guard"] = state
    return state


def _extract_python_code(command: str) -> str:
    """Return the Python body of every AppWorld execute here-doc.

    Multiple execute blocks in one shell command are concatenated so a friend
    mutation in one block cannot hide from a payment-request call in another.
    """
    blocks = [m.group("code") for m in _HEREDOC_BODY_RE.finditer(command)]
    if blocks:
        code = "\n".join(block for block in blocks if block.strip())
        if code.strip():
            return code
    return command


def _call_attr(node: ast.Call) -> str:
    """Return ``apis.venmo.add_friend``-style dotted names, or ''."""
    func = node.func
    parts: list[str] = []
    while isinstance(func, ast.Attribute):
        parts.append(func.attr)
        func = func.value
    if isinstance(func, ast.Name):
        parts.append(func.id)
    return ".".join(reversed(parts)).lower()


def _parse_calls(code: str) -> list[ast.Call]:
    try:
        tree = ast.parse(code)
    except Exception:
        return []
    return [node for node in ast.walk(tree) if isinstance(node, ast.Call)]


def _has_call(code: str, suffix: str) -> bool:
    suffix = suffix.lower()
    for call in _parse_calls(code):
        if _call_attr(call).endswith(suffix):
            return True
    return False


def _task_asks_to_add_friend(question: str) -> bool:
    instruction = _instruction(question).lower()
    if "do not add" in instruction:
        return False
    if "add_friend" in instruction:
        return True
    return bool(_FRIEND_ADD_RE.search(instruction))


def _bounded_block(state: dict, key: str, limit: int = 2) -> bool:
    """Return True when the guard should still block, and count the block."""
    count = int(state.get(key, 0))
    if count >= limit:
        return False
    state[key] = count + 1
    return True


async def before_tool(name: str, args: dict, ctx) -> Any:
    if name != "shell" or not _is_appworld(ctx):
        return None
    command = _get_command(args)
    if not command or _EXECUTE_MARKER not in command:
        return None

    code = _extract_python_code(command)
    if not (
        _has_call(code, "apis.venmo.add_friend")
        and _has_call(code, "apis.venmo.create_payment_request")
    ):
        return None

    if _task_asks_to_add_friend(ctx.question or ""):
        return None

    state = _state(ctx)
    if not _bounded_block(state, "add_friend_blocks"):
        return None

    ctx.trace.event(
        "appworld_mutation_guard_add_friend_blocked",
        blocks=state["add_friend_blocks"],
    )
    return {
        "action": "skip",
        "result": (
            "The AppWorld command was NOT executed because it calls "
            "`apis.venmo.add_friend` together with "
            "`apis.venmo.create_payment_request`, and the task does not ask "
            "you to add a friend. The `create_payment_request` API does not "
            "require friendship: it only needs the receiver's `user_email`, "
            "the `amount`, your `access_token`, and the optional "
            "`description`. Remove the `add_friend` call and retry the same "
            "payment requests without adding any Venmo friend."
        ),
    }

texts.c12b6c213eca4d316b49d62a05c311c7b7c2a54a:
"""Deterministic pre-completion semantic guards.

Before a ``supervisor.complete_task`` call is allowed to run, cheap
deterministic checks catch clear violations of task wording in the executed
shell history. These run before the side-LLM audit and are intentionally narrow:

* relationship sets must be resolved from the authoritative phone-contact
  source when the task names friends/roommates/coworkers/siblings/relatives;
* Spotify song/album library tasks must be read from ``show_song_library`` /
  ``show_album_library`` rather than ``show_liked_songs`` / ``show_liked_albums``;
* a playlist creation must not leave ``is_public`` to the API default; and
* a "most-liked" question must verify the private, user-specific liked signal
  rather than only the public like count.
* a paginated list query that returned a full page must be followed by later
  ``page_index`` pagination before completion; and
* when a task asks for "songs in my playlists which I have liked",
  ``show_liked_playlists`` output is a playlist list, not the target song set,
  so a tool-result nudge reminds the model to intersect liked songs with owned
  playlist songs.

Each guard is bounded: after ``_MAX_SKIPS`` skips in a run, or on the final
usable tool turn, the completion call is allowed through so a run can still
finish. Guards are skipped for non-AppWorld tasks.
"""

from __future__ import annotations

import re

_COMPLETION_CALL_RE = re.compile(r"\.complete_task\s*\(")
_RELATIONSHIP_WORDS = ("friend", "roommate", "coworker", "sibling", "relative")
_PHONE_SOURCE_CALLS = (
    "search_contacts(",
    "show_contact_relationships(",
)
_VENMO_SOCIAL_CALLS = (
    "search_friends(",
)
_PRIVATE_LIKED_CALLS = (
    "show_liked_songs(",
    "show_song_privates(",
    "show_album_privates(",
)
_SONG_LIBRARY_CALL = "show_song_library"
_ALBUM_LIBRARY_CALL = "show_album_library"
_LIKED_SONGS_CALL = "show_liked_songs"
_LIKED_ALBUMS_CALL = "show_liked_albums"
_PLAYLIST_CREATION_WORDS = ("create", "new", "add")
_MAX_SKIPS = 3
_MAX_LIKED_PLAYLIST_NUDGES = 2
_MAX_LIBRARY_NUDGES = 2

_PAGE_LIMIT_RE = re.compile(r"page_limit\s*=\s*(\d+)")
_LIST_ITEM_FIELDS = (
    "transaction_id",
    "email_thread_id",
    "song_id",
    "playlist_id",
    "contact_id",
    "text_message_id",
    "album_id",
    "artist_id",
)
_LIKED_SONGS_IN_PLAYLISTS_RE = re.compile(
    r"songs?\s+in\s+my\s+(?:spotify\s+)?playlists?\s+(?:which|that)\s+i\s+have\s+liked",
    re.IGNORECASE,
)


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _task_instruction(question: str) -> str:
    """Return the first paragraph, which is normally the task itself."""
    question = (question or "").strip()
    idx = question.find("\n\n")
    return (question[:idx] if idx != -1 else question).strip()


def _is_appworld_run(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    return "appworld_client.py" in question or "Supervisor:" in question


def _executed_commands(ctx) -> list[str]:
    """Return commands from executed shell tool calls, most recent last."""
    commands: list[str] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if command:
            commands.append(command)
    return commands


def _executed_records(ctx) -> list[tuple[int, str, str]]:
    """Return ``(seq, command, result)`` for executed shell calls."""
    records: list[tuple[int, str, str]] = []
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if not command:
            continue
        result = (
            getattr(rec, "result_full", None)
            or getattr(rec, "result_preview", "")
            or ""
        )
        records.append((rec.seq, command, result))
    return records


def _has(commands: list[str], needles) -> bool:
    return any(needle in command for command in commands for needle in needles)


def _has_call(commands: list[str], func_name: str) -> bool:
    """True when ``func_name`` is called with a ``(`` in any command."""
    pattern = re.compile(re.escape(func_name) + r"\s*\(")
    return any(pattern.search(command) for command in commands)


def _iter_call_args(command: str, func_name: str):
    """Yield the balanced argument text for each ``func_name(...)`` call."""
    marker = func_name + "("
    idx = 0
    while True:
        idx = command.find(marker, idx)
        if idx < 0:
            break
        start = idx + len(marker)
        depth = 1
        i = start
        quote: str | None = None
        escaped = False
        while i < len(command) and depth > 0:
            char = command[i]
            if quote is not None:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
            else:
                if char in ("'", '"'):
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
            i += 1
        if depth == 0:
            yield command[start : i - 1]
        idx = i


def _has_create_playlist_without_visibility(commands: list[str]) -> bool:
    for command in commands:
        if "create_playlist(" not in command:
            continue
        for args in _iter_call_args(command, "create_playlist"):
            if "is_public" not in args:
                return True
    return False


def _library_needs(instruction: str) -> tuple[bool, bool]:
    """Return ``(needs_song_library, needs_album_library)`` for a task wording."""
    instruction = instruction.lower()
    need_song = "song library" in instruction
    need_album = "album library" in instruction
    if "song and album library" in instruction:
        need_song = need_album = True
    return need_song, need_album


def _library_source_violation(instruction: str, commands: list[str]) -> str | None:
    """Return a message when a library task used liked-* APIs instead of library APIs.

    AppWorld has separate ``show_song_library``/``show_album_library`` and
    ``show_liked_songs``/``show_liked_albums`` endpoints. A task that names the
    user's song or album library must be derived from the library endpoint; the
    liked-* collections are a different, smaller set and produce verifier
    failures when used as a substitute.
    """
    need_song, need_album = _library_needs(instruction)

    wrong: list[str] = []
    if (
        need_song
        and not _has_call(commands, _SONG_LIBRARY_CALL)
        and _has_call(commands, _LIKED_SONGS_CALL)
    ):
        wrong.append("song library")
    if (
        need_album
        and not _has_call(commands, _ALBUM_LIBRARY_CALL)
        and _has_call(commands, _LIKED_ALBUMS_CALL)
    ):
        wrong.append("album library")

    if not wrong:
        return None

    label = " and ".join(wrong)
    return (
        f"the task refers to the Spotify {label}, but the executed history queried "
        "show_liked_songs/show_liked_albums and never queried the library API(s). "
        "Re-read the correct library with apis.spotify.show_song_library / "
        "apis.spotify.show_album_library, then re-derive and verify the target set "
        "before completing."
    )


def _library_source_nudge(ctx, command: str) -> str | None:
    """Nudge immediately when a liked-* API is fetched for a library task."""
    need_song, need_album = _library_needs(_task_instruction(ctx.question))
    if not (need_song or need_album):
        return None

    previous_commands = _executed_commands(ctx)
    all_commands = previous_commands + [command]

    notes: list[str] = []
    if (
        need_song
        and _has_call([command], _LIKED_SONGS_CALL)
        and not _has_call(all_commands, _SONG_LIBRARY_CALL)
    ):
        notes.append(
            "show_liked_songs returns the songs you have liked, not your Spotify "
            "song library. Use apis.spotify.show_song_library for song-library tasks."
        )
    if (
        need_album
        and _has_call([command], _LIKED_ALBUMS_CALL)
        and not _has_call(all_commands, _ALBUM_LIBRARY_CALL)
    ):
        notes.append(
            "show_liked_albums returns the albums you have liked, not your Spotify "
            "album library. Use apis.spotify.show_album_library for album-library tasks."
        )

    return " ".join(notes) if notes else None


def _block(ctx, state, message: str):
    state["skips"] = state.get("skips", 0) + 1
    # Require a fresh state-read after this feedback before the next retry.
    checkpoint = ctx.state.setdefault("pre_completion_checkpoint", {})
    checkpoint["checkpoint_seq"] = getattr(ctx, "_tool_seq", 0)
    checkpoint["retries"] = 0
    return {
        "action": "skip",
        "result": (
            "Blocked supervisor.complete_task call by pre_completion_guards: "
            + message
            + " Run the missing verification/fix through the shell tool, then "
            "call supervisor.complete_task again."
        ),
    }


def _page_limit(command: str) -> int | None:
    match = _PAGE_LIMIT_RE.search(command)
    return int(match.group(1)) if match else None


def _count_item_markers(result: str) -> int:
    if not result:
        return 0
    counts = [result.count(field) for field in _LIST_ITEM_FIELDS]
    return max(counts, default=0)


def _is_pagination_followup(command: str) -> bool:
    """True when a command explicitly requests a later page or loops pages."""
    if re.search(r"page_index\s*=\s*[1-9]", command):
        return True
    if (" for " in command or " while " in command) and "page_index" in command:
        return True
    return False


def _has_unpaginated_full_page(ctx) -> bool:
    """True when an executed full page was never followed by later pagination."""
    records = _executed_records(ctx)
    for seq, command, result in records:
        limit = _page_limit(command)
        if not limit:
            continue
        if _count_item_markers(result) < limit:
            continue
        # The command itself may already paginate in a loop.
        if _is_pagination_followup(command):
            continue
        if any(
            later_seq > seq and _is_pagination_followup(later_command)
            for later_seq, later_command, _ in records
        ):
            continue
        return True
    return False


def _is_liked_songs_in_playlists_task(ctx) -> bool:
    instruction = _task_instruction(ctx.question).lower()
    return bool(_LIKED_SONGS_IN_PLAYLISTS_RE.search(instruction))


async def before_tool(name: str, args: dict, ctx):
    if name != "shell":
        return None

    command = _get_command(args)
    if not _COMPLETION_CALL_RE.search(command):
        return None
    if not _is_appworld_run(ctx):
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    if state.get("skips", 0) >= _MAX_SKIPS:
        return None
    if getattr(ctx, "remaining_turns", 100) <= 1:
        return None

    instruction = _task_instruction(ctx.question).lower()
    commands = _executed_commands(ctx)

    # 1. Relationship set must come from the named authoritative source.
    if any(word in instruction for word in _RELATIONSHIP_WORDS):
        if _has(commands, _VENMO_SOCIAL_CALLS) and not _has(
            commands, _PHONE_SOURCE_CALLS
        ):
            return _block(
                ctx,
                state,
                "this task names a relationship set (friends, roommates, "
                "coworkers, siblings, relatives, etc.), but the executed history "
                "resolved targets from Venmo search_friends and never queried the "
                "authoritative phone contacts. Resolve the set with "
                "apis.phone.search_contacts or "
                "apis.phone.show_contact_relationships, then re-verify coverage.",
            )

    # 2. Spotify song/album library must come from library APIs, not liked-*.
    library_msg = _library_source_violation(instruction, commands)
    if library_msg:
        return _block(ctx, state, library_msg)

    # 3. Playlist visibility must be explicit and verified.
    if any(word in instruction for word in _PLAYLIST_CREATION_WORDS) and "playlist" in instruction:
        if _has_create_playlist_without_visibility(commands):
            return _block(
                ctx,
                state,
                "a playlist was created without an explicit is_public argument, so "
                "visibility was left to the API default. Re-create or update the "
                "playlist with is_public set explicitly (use is_public=True unless "
                "the task explicitly requires a private playlist) and verify the "
                "created playlist's is_public value.",
            )

    # 4. "most-liked" must verify the private liked signal, not only like_count.
    if "most-liked" in instruction or "most liked" in instruction:
        if _has(commands, ("like_count",)) and not _has(
            commands, _PRIVATE_LIKED_CALLS
        ):
            return _block(
                ctx,
                state,
                "the task asks for a 'most-liked' item, but the executed history "
                "used only the public like_count metric. Verify the private, "
                "user-specific liked signal as well (for example "
                "show_liked_songs / show_song_privates / show_album_privates) and "
                "recompute the answer from the reading the task wording supports.",
            )

    # 5. A full page from a paginated list query must be followed by pagination.
    if _has_unpaginated_full_page(ctx):
        return _block(
            ctx,
            state,
            "a paginated list query returned a full page but was never followed "
            "by a later page_index (1,2,...). Paginate the complete window/feed "
            "until a short page is observed, then re-verify coverage before "
            "completing.",
        )

    return None


async def after_tool(name: str, args: dict, result: str, ctx):
    """Append bounded nudges when a task-relevant wrong source is fetched."""
    if name != "shell":
        return None
    if not _is_appworld_run(ctx):
        return None

    command = _get_command(args)
    if not command:
        return None

    state = ctx.state.setdefault("pre_completion_guards", {})
    appended: list[str] = []

    # Nudge when a liked-playlist API is fetched for a liked-songs task.
    if (
        "show_liked_playlists(" in command
        and _is_liked_songs_in_playlists_task(ctx)
    ):
        count = state.get("liked_playlist_nudges", 0)
        if count < _MAX_LIKED_PLAYLIST_NUDGES:
            state["liked_playlist_nudges"] = count + 1
            appended.append(
                "[pre_completion_guards] show_liked_playlists returns the "
                "playlists you have liked, not the songs in your playlists which you "
                "have liked. The target set is show_liked_songs(...) intersected with "
                "the song IDs in your owned playlists (show_playlist / "
                "show_playlist_library). Do not act on liked-playlist songs directly; "
                "verify the intersection before rating or completing."
            )

    # Nudge when a liked-* API is fetched for a song/album library task.
    library_nudge = _library_source_nudge(ctx, command)
    if library_nudge:
        count = state.get("library_nudges", 0)
        if count < _MAX_LIBRARY_NUDGES:
            state["library_nudges"] = count + 1
            appended.append("[pre_completion_guards] " + library_nudge)

    if not appended:
        return None
    return result + "\n\n" + "\n\n".join(appended)

texts.caf052a6d3f537dacc9b749fca0fa38726cee122:
"""Guard final answers and supervisor.complete_task submissions.

Three reported failure modes are cheap to catch deterministically:

  1. The run ends with prose or an unexecuted command instead of a real
     ``apis.supervisor.complete_task`` call.  ``before_final`` therefore
     continues the turn when a final candidate is clearly a shell command or
     when an AppWorld run has used ``apis`` but never successfully completed
     the task.

  2. ``complete_task`` is called with a long/prose answer on a non-question
     action task.  ``before_tool`` skips such calls before they reach the
     supervisor and tells the model the documented format.

  3. A question task submits an answer that is missing or still looks like
     prose even when short.  ``before_tool`` also enforces the documented
     "concise canonical answer" format for question tasks.

The completion detector deliberately looks for an actual
``(apis.)supervisor.complete_task(...)`` invocation rather than any shell
command containing the string ``complete_task``, so reading the API docs does
not count as having completed the task.
"""

from __future__ import annotations

import re

_DSML_MARKERS = (
    "<｜｜DSML｜｜",
    "<|DSML|",
    "<dsml",
    "<tool_calls>",
    "<function_calls>",
)

_COMPLETE_CALL_RE = re.compile(r"\b(?:apis\.)?supervisor\.complete_task\s*\(")


def _get_command(args) -> str:
    if not isinstance(args, dict):
        return ""
    command = args.get("command", "")
    return command if isinstance(command, str) else ""


def _strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:[A-Za-z0-9_+-]+)?\s*", "", text, count=1)
        text = re.sub(r"\s*```$", "", text)
    return text.strip()


def _looks_like_unexecuted_command(answer: str) -> bool:
    text = answer or ""
    if any(marker in text for marker in _DSML_MARKERS):
        return True
    stripped = _strip_code_fences(text)
    if not stripped:
        return False
    first_line = stripped.splitlines()[0].strip()
    if first_line.startswith(
        ("cd /opt/flashrsi-lite", "/opt/flashrsi-lite", "print(apis.", "apis.")
    ):
        return True
    if "appworld_client.py execute" in first_line:
        return True
    return False


def _used_appworld(ctx) -> bool:
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        command = _get_command(rec.requested_args)
        if "appworld_client.py" in command or "apis." in command:
            return True
    return False


def _is_complete_task_call(command: str) -> bool:
    """True only for a real ``supervisor.complete_task(...)`` invocation."""
    return bool(_COMPLETE_CALL_RE.search(command))


def _has_completed(ctx) -> bool:
    for rec in getattr(ctx, "tool_history", []) or []:
        if rec.requested_name != "shell":
            continue
        if getattr(rec, "action", "executed") != "executed":
            continue
        command = _get_command(rec.requested_args)
        if _is_complete_task_call(command):
            return True
    return False


def _needs_completion_call(ctx) -> bool:
    question = getattr(ctx, "question", "") or ""
    if "appworld_client.py" not in question and "Supervisor:" not in question:
        return False
    return _used_appworld(ctx) and not _has_completed(ctx)


def _extract_complete_task_params(command: str) -> str | None:
    """Return the argument text inside the complete_task(...) call, if any."""
    idx = command.find("complete_task(")
    if idx < 0:
        return None
    start = idx + len("complete_task(")
    depth = 1
    i = start
    quote: str | None = None
    escaped = False
    while i < len(command) and depth > 0:
        char = command[i]
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
        else:
            if char in ("'", '"'):
                quote = char
            elif char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
        i += 1
    if depth != 0:
        return None
    return command[start : i - 1]


def _answer_info(params: str):
    """Return (present, kind, value) for the answer= argument."""
    if not re.search(r"\banswer\s*=", params):
        return False, "absent", None
    if re.search(r"\banswer\s*=\s*(None|null)\b", params):
        return True, "none", None
    m = re.search(r"\banswer\s*=\s*([\"'])(.*?)\1", params, re.DOTALL)
    if m:
        return True, "string", m.group(2)
    m = re.search(r"\banswer\s*=\s*(-?\d+(?:\.\d+)?)", params)
    if m:
        return True, "number", m.group(1)
    return True, "other", None


def _is_question_task(ctx) -> bool:
    return "?" in (getattr(ctx, "question", "") or "")


def _looks_like_prose_answer(value: str | None) -> bool:
    """Conservative check for prose/markdown where a canonical value is due."""
    text = (value or "").strip()
    if not text:
        return True
    if "\n" in text or "\r" in text:
        return True
    if len(text) > 120:
        return True
    low = text.lower()
    if low.startswith(("answer:", "**answer:", "the answer is", "task complete", "task:")):
        return True
    if " — " in text or ";" in text or "|" in text:
        return True
    if re.match(r"^[-*#>]", text):
        return True
    return False


async def before_tool(name, args, ctx):
    if name != "shell":
        return None
    command = _get_command(args)
    if "complete_task" not in command:
        return None

    params = _extract_complete_task_params(command)
    if params is None:
        return None

    present, kind, value = _answer_info(params)

    if not _is_question_task(ctx):
        if present and kind != "none":
            return {
                "action": "skip",
                "result": (
                    "Blocked supervisor.complete_task call: this task is not a "
                    "question, so the supervisor API requires answer=None (or the "
                    "answer argument omitted). Reissue the shell command as "
                    "apis.supervisor.complete_task() or complete_task(answer=None)."
                ),
            }
        return None

    # Question task: an answer is mandatory and must be the concise canonical
    # value, not prose.  Keep the threshold deliberately tight; multi-word
    # titles and numeric values stay well below it.
    if not present or kind in ("none", "absent") or kind == "other":
        return {
            "action": "skip",
            "result": (
                "Blocked supervisor.complete_task call: this task is a question, "
                "so the supervisor API requires answer=<exact concise value> "
                "(a number, yes/no, a name/title, or a short comma-separated "
                "list). Reissue the shell command with that value."
            ),
        }

    if kind == "string" and _looks_like_prose_answer(value):
        return {
            "action": "skip",
            "result": (
                "Blocked supervisor.complete_task call: the answer looks like "
                "prose. For question tasks pass the exact concise canonical "
                "answer (a number, yes/no, name, or short list), not a "
                "descriptive paragraph or markdown."
            ),
        }

    return None


async def before_final(answer, ctx):
    if _looks_like_unexecuted_command(answer):
        return {
            "action": "continue",
            "feedback": (
                "Your final message looks like a shell command or DSML markup "
                "emitted as text, so it will not execute. Issue the command "
                "through the shell tool, wait for its result, and then return "
                "plain text only."
            ),
        }

    if _needs_completion_call(ctx):
        return {
            "action": "continue",
            "feedback": (
                "You have used AppWorld APIs but have not yet marked the task "
                "complete. Call apis.supervisor.complete_task through the "
                "shell tool with the documented answer format (answer=None "
                "for action tasks, exact concise answer for question tasks), "
                "then return a short plain-text final message."
            ),
        }

    return None

